attest/_hidden_runner.py:
"""Runs one hidden test file inside a task workspace (executed in a subprocess).

Usage: python -I _hidden_runner.py <hidden_test.py> <workspace>

Prints one line: ``__HIDDEN_RESULT__ {"name": {"passed": bool, "error": str}, ...}``
"""

import importlib.util
import json
import os
import sys

MARKER = "__HIDDEN_RESULT__"
# Optional business-policy guard (exploratory, D38): with ATTEST_POLICY_GUARD=1, every money field
# passed to ledgerly.audit.record during the hidden tests must be a Decimal. The guard is installed
# before the hidden tests import the solution, so `from .audit import record` is covered too.
POLICY_TEST = "test_conv_c1_policy_audit_amounts_are_decimal"


def _install_policy_guard(violations: list) -> None:
    from decimal import Decimal

    import ledgerly.audit as audit

    original = audit.record

    def guarded(event, **fields):
        for key, value in fields.items():
            if "amount" in key and value is not None and not isinstance(value, Decimal):
                violations.append(f"{event}: {key}={value!r} ({type(value).__name__})")
        return original(event, **fields)

    audit.record = guarded


def _reset_state() -> None:
    audit = sys.modules.get("ledgerly.audit")
    if audit is not None and hasattr(audit, "clear"):
        audit.clear()


def main() -> None:
    hidden_path, workspace = sys.argv[1], sys.argv[2]
    sys.path[:0] = [workspace, os.path.dirname(os.path.abspath(hidden_path))]
    results: dict[str, dict] = {}
    violations: list[str] = []
    guard = os.environ.get("ATTEST_POLICY_GUARD") == "1"
    if guard:
        try:
            _install_policy_guard(violations)
        except BaseException as exc:  # noqa: BLE001 - no ledgerly in this workspace: nothing to guard
            guard = False
    try:
        spec = importlib.util.spec_from_file_location("hidden_test", hidden_path)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
    except BaseException as exc:  # noqa: BLE001 - report import failures as data
        print(MARKER, json.dumps({"__import__": {"passed": False, "error": f"{type(exc).__name__}: {exc}"[:500]}}))
        return
    for name, fn in vars(module).items():
        if not (name.startswith("test_") and callable(fn)):
            continue
        _reset_state()
        try:
            fn()
            results[name] = {"passed": True, "error": ""}
        except BaseException as exc:  # noqa: BLE001
            results[name] = {"passed": False, "error": f"{type(exc).__name__}: {exc}"[:500]}
    if guard:
        results[POLICY_TEST] = {"passed": not violations, "error": "; ".join(violations[:5])[:500]}
    print(MARKER, json.dumps(results))


if __name__ == "__main__":
    main()

attest/analysis.py:
"""Turns result.json files into the numbers reported in the README and the HTML report.

Every number in the write-up must be computable by this module from files in runs/,
so a reviewer can recompute it. Nothing here calls a model.
"""

from __future__ import annotations

import json
import random
import re
from collections import defaultdict
from pathlib import Path

from .memory import CONDITIONS

GROUPS = ("experience", "heldout", "control", "stale")


def load_results(root: Path) -> list[dict]:
    return [json.loads(p.read_text()) for p in sorted(Path(root).rglob("result.json"))]


def usable(results: list[dict]) -> tuple[list[dict], list[dict]]:
    """Split into (kept, excluded). Runs that touched benchmark files are excluded (preregistered rule)."""
    kept = [r for r in results if not r.get("leaks")]
    return kept, [r for r in results if r.get("leaks")]


def _rate(rs: list[dict], key: str) -> float | None:
    return sum(bool(r[key]) for r in rs) / len(rs) if rs else None


def headline(results: list[dict]) -> list[dict]:
    """One row per (condition, group): pass@1, pass@2, mean steps, mean cost, spread across repetitions."""
    by = defaultdict(list)
    for r in results:
        by[(r["condition"], r["group"])].append(r)
    rows = []
    for cond in [c for c in CONDITIONS if any(k[0] == c for k in by)]:
        for group in GROUPS:
            rs = by.get((cond, group), [])
            if not rs:
                continue
            per_rep = defaultdict(list)
            for r in rs:
                per_rep[r.get("rep", 1)].append(r)
            rep_rates = [_rate(v, "first_pass") for v in per_rep.values()]
            rows.append({
                "condition": cond,
                "group": group,
                "runs": len(rs),
                "pass1": _rate(rs, "first_pass"),
                "pass2": _rate(rs, "final_pass"),
                "pass1_min": min(rep_rates),
                "pass1_max": max(rep_rates),
                "steps": sum(r["steps"] for r in rs) / len(rs),
                "cost_usd": sum(r["cost_usd"] for r in rs) / len(rs),
                "notes_shown": sum(len(r["shown_notes"]) for r in rs) / len(rs),
            })
    return rows


def per_task(results: list[dict]) -> dict[str, dict[str, dict]]:
    """task_id -> condition -> {"pass1": k, "runs": n, "missed": {convention: count}}."""
    table: dict[str, dict[str, dict]] = defaultdict(dict)
    for r in results:
        cell = table[r["task_id"]].setdefault(r["condition"], {"pass1": 0, "runs": 0, "missed": defaultdict(int)})
        cell["runs"] += 1
        cell["pass1"] += bool(r["first_pass"])
        if not r["attempts"][0].get("crashed"):  # a crash is a failure, but not a convention miss
            for c in r["attempts"][0]["conv_failed"]:
                cell["missed"][c] += 1
    return {t: {c: dict(v, missed=dict(v["missed"])) for c, v in conds.items()} for t, conds in sorted(table.items())}


def regressions(results: list[dict], baseline: str = "no_memory") -> list[dict]:
    """Tasks where a memory condition passes on the first attempt LESS often than the no-memory baseline."""
    out = []
    for task_id, conds in per_task(results).items():
        base = conds.get(baseline)
        if not base:
            continue
        for cond, cell in conds.items():
            if cond == baseline:
                continue
            if cell["pass1"] / cell["runs"] < base["pass1"] / base["runs"]:
                out.append({"task_id": task_id, "condition": cond,
                            "memory": f"{cell['pass1']}/{cell['runs']}", "baseline": f"{base['pass1']}/{base['runs']}"})
    return out


TIERS = {"discoverable": ("C1", "C2", "C3", "C4"), "review_only": ("C5", "C6")}


def convention_hits(results: list[dict]) -> list[dict]:
    """Per condition and convention: how often the first attempt satisfied it (crashes excluded)."""
    counts = defaultdict(lambda: [0, 0])  # (condition, convention) -> [satisfied, checked]
    for r in results:
        first = r["attempts"][0]
        if first.get("crashed"):
            continue
        for conv in r.get("conventions", []):
            cell = counts[(r["condition"], conv)]
            cell[1] += 1
            cell[0] += conv not in first["conv_failed"]
    rows = []
    for (cond, conv), (ok, n) in sorted(counts.items()):
        tier = next((t for t, cs in TIERS.items() if conv in cs), "simkit")
        rows.append({"condition": cond, "convention": conv, "tier": tier, "satisfied": ok, "checked": n, "rate": ok / n})
    return rows


def contamination(results: list[dict]) -> list[dict]:
    """For control tasks (simkit): how many notes learned on another repository were shown, per condition."""
    rows = defaultdict(lambda: {"runs": 0, "foreign_notes_shown": 0, "pass1": 0})
    for r in results:
        if r["group"] != "control":
            continue
        row = rows[r["condition"]]
        row["runs"] += 1
        row["pass1"] += bool(r["first_pass"])
        row["foreign_notes_shown"] += len(r["shown_notes"])  # every note so far was learned on ledgerly
    return [{"condition": c, **v} for c, v in rows.items()]


def stale_timeline(results: list[dict]) -> list[dict]:
    """Stale-phase runs in order with the memory events they caused (for the recovery story)."""
    rows = []
    for r in sorted((r for r in results if r["group"] == "stale"), key=lambda r: (r["condition"], r.get("rep", 1), r["task_id"])):
        changes = [
            {"id": e.get("id") or (e.get("item") or {}).get("id"), "type": e["type"], "reason": e.get("reason", "")}
            for e in r.get("memory_events", [])
            if e["type"] in ("add", "reject") or "status" in (e.get("fields") or {})
        ]
        rows.append({
            "condition": r["condition"], "rep": r.get("rep", 1), "task_id": r["task_id"],
            "first_pass": r["first_pass"], "final_pass": r["final_pass"],
            "shown": r["shown_notes"], "cited": r["cited_notes"],
            "version_warnings": (r.get("retrieval_debug") or {}).get("version_warnings", []),
            "missed": r["attempts"][0]["conv_failed"], "memory_changes": changes,
        })
    return rows


# ---------------------------------------------------------------- tiers, paired comparison, attribution

REVIEW_ONLY = set(TIERS["review_only"])


def task_tier(r: dict) -> str:
    convs = set(r.get("conventions", []))
    if not convs or convs <= {"K1", "K2"}:
        return "simkit"
    return "review_only" if convs & REVIEW_ONLY else "discoverable"


def _tokens(r: dict) -> int:
    return sum((a.get("tokens") or {}).get("prompt", 0) + (a.get("tokens") or {}).get("completion", 0) for a in r["attempts"])


def tier_split(results: list[dict], group: str = "heldout") -> list[dict]:
    """pass@1, steps and tokens per condition, for tasks that need review-only knowledge vs tasks that do not."""
    by = defaultdict(list)
    for r in results:
        if r["group"] == group:
            by[(r["condition"], task_tier(r))].append(r)
    rows = []
    for (cond, tier), rs in sorted(by.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, kv[0][1])):
        rows.append({"condition": cond, "tier": tier, "runs": len(rs), "pass1": _rate(rs, "first_pass"),
                     "steps": sum(r["steps"] for r in rs) / len(rs), "tokens": sum(_tokens(r) for r in rs) / len(rs)})
    return rows


def paired(results: list[dict], group: str = "heldout", baseline: str = "no_memory",
           resamples: int = 10000, seed: int = 0) -> list[dict]:
    """Per-task pass@1 difference against the baseline, with a bootstrap 95% interval over tasks.

    Repetitions of the same task are averaged first, so the unit of analysis is the task.
    """
    rates: dict[str, dict[str, list]] = defaultdict(lambda: defaultdict(list))
    for r in results:
        if r["group"] == group:
            rates[r["condition"]][r["task_id"]].append(bool(r["first_pass"]))
    base = {t: sum(v) / len(v) for t, v in rates.get(baseline, {}).items()}
    rng = random.Random(seed)
    rows = []
    for cond, per_task in rates.items():
        if cond == baseline:
            continue
        tasks = sorted(set(per_task) & set(base))
        if not tasks:
            continue
        diffs = [sum(per_task[t]) / len(per_task[t]) - base[t] for t in tasks]
        boots = sorted(sum(rng.choice(diffs) for _ in diffs) / len(diffs) for _ in range(resamples))
        rows.append({
            "condition": cond, "tasks": len(tasks), "mean_diff": sum(diffs) / len(diffs),
            "ci_low": boots[int(0.025 * resamples)], "ci_high": boots[int(0.975 * resamples) - 1],
            "wins": sum(d > 0 for d in diffs), "losses": sum(d < 0 for d in diffs), "ties": sum(d == 0 for d in diffs),
        })
    return sorted(rows, key=lambda x: CONDITIONS.index(x["condition"]) if x["condition"] in CONDITIONS else 99)


CONVENTION_PATTERNS = {
    "C1": r"round_money|half[- ]up|ROUND_HALF|quantiz|two decimal|2 decimal|Decimal",
    "C2": r"BillingError",
    "C3": r"ensure_utc|time[- ]?zone|tz-aware|aware UTC|naive",
    "C4": r"audit\.record|audit entr|audit trail|audit log",
    "C5": r"idempoten",
    "C6": r"approv",
}
NOTE_RE = re.compile(r"\[((?:at|rb|ace)-\d{4})\](.*?)(?=\n\s*-?\s*\[(?:at|rb|ace)-\d{4}\]|\n## |\Z)", re.S)


def _notes_by_id(context: str) -> dict[str, str]:
    return {m.group(1): m.group(2) for m in NOTE_RE.finditer(context or "")}


def attribution(results: list[dict]) -> list[dict]:
    """Was a note about convention X shown or cited, and did the first attempt actually satisfy X?

    Judged from behaviour (the hidden test for X), not from the agent's own claim.
    """
    cells = defaultdict(lambda: defaultdict(int))
    for r in results:
        first = r["attempts"][0]
        if first.get("crashed") or r["condition"] == "no_memory":
            continue
        notes = _notes_by_id(r.get("notes_context", ""))
        cited = set(r.get("cited_notes", []))
        for conv in r.get("conventions", []):
            pattern = CONVENTION_PATTERNS.get(conv)
            if not pattern:
                continue
            related = {i for i, text in notes.items() if re.search(pattern, text, re.I)}
            ok = conv not in first["conv_failed"]
            c = cells[(r["condition"], conv)]
            c["checked"] += 1
            if related:
                c["shown"] += 1
                c["shown_ok"] += ok
                if related & cited:
                    c["cited"] += 1
                    c["cited_ok"] += ok
                elif ok:
                    c["followed_uncited"] += 1
            else:
                c["not_shown"] += 1
                c["not_shown_ok"] += ok
    rows = []
    for (cond, conv), c in sorted(cells.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, kv[0][1])):
        rows.append({"condition": cond, "convention": conv, **dict(c),
                     "ok_when_shown": c["shown_ok"] / c["shown"] if c["shown"] else None,
                     "ok_when_not_shown": c["not_shown_ok"] / c["not_shown"] if c["not_shown"] else None})
    return rows


def transfer_split(results: list[dict]) -> list[dict]:
    """Held-out pass@1 split into near transfer (H06, H07, H11 mirror an experience task) and far transfer. Exploratory."""
    from .benchmark import load_task

    kind = {}
    cells = defaultdict(list)
    for r in results:
        if r["group"] != "heldout" or r["attempts"][0].get("crashed"):
            continue
        kind.setdefault(r["task_id"], load_task(r["task_id"]).transfer or "far")
        cells[(r["condition"], kind[r["task_id"]])].append(bool(r["first_pass"]))
    return [{"condition": c, "transfer": t, "runs": len(v), "pass@1": sum(v) / len(v)}
            for (c, t), v in sorted(cells.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, kv[0][1]))]


def stale_split(results: list[dict]) -> list[dict]:
    """Stale pass@1 for the threshold tasks (S04, S05), which can detect outdated memory, and for the
    rounding tasks (S01-S03), which are "no false recall" checks (audit M3). Preregistered for H3."""
    cells = defaultdict(list)
    for r in results:
        if r["group"] != "stale" or r["attempts"][0].get("crashed"):
            continue
        part = "threshold (S04, S05)" if r["task_id"] in ("S04", "S05") else "rounding (S01-S03)"
        cells[(r["condition"], part)].append(bool(r["first_pass"]))
    return [{"condition": c, "tasks": p, "runs": len(v), "pass@1": sum(v) / len(v)}
            for (c, p), v in sorted(cells.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, kv[0][1]))]


# ---------------------------------------------------------------- preregistered decision rules (PREREGISTRATION 5)

DELTA = 0.10  # non-inferiority margin, fixed before any memory run: about one of the 11 held-out tasks lost
SUPPORTED, INSUFFICIENT, NOT_SUPPORTED = "supported", "direction consistent, insufficient evidence", "not supported"


def compare(results: list[dict], group: str, condition: str, baseline: str, tasks: set[str] | None = None,
            resamples: int = 10000, seed: int = 0) -> dict | None:
    """Paired per-task difference of pass@1 (condition - baseline), repetitions averaged first, bootstrap
    95% interval with the task as the resampling unit (never the individual run)."""
    rates: dict[str, dict[str, list]] = defaultdict(lambda: defaultdict(list))
    for r in results:
        if r["group"] == group and (tasks is None or r["task_id"] in tasks):
            rates[r["condition"]][r["task_id"]].append(bool(r["first_pass"]))
    common = sorted(set(rates.get(condition, {})) & set(rates.get(baseline, {})))
    if not common:
        return None
    mean = lambda v: sum(v) / len(v)  # noqa: E731
    diffs = [mean(rates[condition][t]) - mean(rates[baseline][t]) for t in common]
    rng = random.Random(seed)
    boots = sorted(sum(rng.choice(diffs) for _ in diffs) / len(diffs) for _ in range(resamples))
    return {"condition": condition, "baseline": baseline, "group": group, "tasks": len(common),
            "mean_diff": mean(diffs), "ci_low": boots[int(0.025 * resamples)], "ci_high": boots[int(0.975 * resamples) - 1],
            "wins": sum(d > 0 for d in diffs), "losses": sum(d < 0 for d in diffs), "ties": sum(d == 0 for d in diffs)}


def superiority(c: dict | None) -> str | None:
    """Supported only if the whole interval is above 0; a positive estimate whose interval reaches 0 is insufficient."""
    if c is None:
        return None
    if c["ci_low"] > 0:
        return SUPPORTED
    return INSUFFICIENT if c["mean_diff"] > 0 else NOT_SUPPORTED


def non_inferiority(c: dict | None, delta: float = DELTA) -> str | None:
    """Supported if the interval stays above -delta; not supported if the estimate itself is at or below -delta."""
    if c is None:
        return None
    if c["ci_low"] > -delta:
        return SUPPORTED
    return INSUFFICIENT if c["mean_diff"] > -delta else NOT_SUPPORTED


def _all(*verdicts):
    if any(v is None for v in verdicts):
        return None
    if all(v == SUPPORTED for v in verdicts):
        return SUPPORTED
    return NOT_SUPPORTED if any(v == NOT_SUPPORTED for v in verdicts) else INSUFFICIENT


def hypothesis_tests(results: list[dict]) -> list[dict]:
    """H1-H6 exactly as preregistered (PREREGISTRATION section 4, including its decision rules)."""
    foreign_by = {c["condition"]: c.get("foreign_notes_shown") for c in contamination(results)}
    regress = defaultdict(int)
    for r in regressions(results):
        if r["task_id"][0] in "HB":
            regress[r["condition"]] += 1
    out = []

    h1 = compare(results, "heldout", "attest", "no_memory")
    out.append({"id": "H1", "type": "superiority", "verdict": superiority(h1), "tests": [h1]})

    foreign = foreign_by.get("attest")
    b = compare(results, "control", "attest", "no_memory")
    h2 = None if foreign is None else (SUPPORTED if foreign == 0 else NOT_SUPPORTED)
    out.append({"id": "H2", "type": "leakage count (exact); control pass@1 descriptive", "verdict": h2,
                "foreign_notes_shown": foreign, "tests": [b]})

    s_all = compare(results, "stale", "attest", "no_memory")
    s_thr = compare(results, "stale", "attest", "no_memory", tasks={"S04", "S05"})
    out.append({"id": "H3", "type": "non-inferiority (all stale tasks and threshold tasks S04-S05)",
                "verdict": _all(non_inferiority(s_all), non_inferiority(s_thr)), "tests": [s_all, s_thr]})

    rb = compare(results, "heldout", "attest", "reasoningbank")
    ace = compare(results, "heldout", "attest", "ace")
    out.append({"id": "H4", "type": "non-inferiority vs each baseline", "verdict": _all(non_inferiority(rb), non_inferiority(ace)),
                "tests": [rb, ace], "regressions": {c: regress.get(c, 0) for c in ("attest", "reasoningbank", "ace")}})

    ns_foreign = foreign_by.get("attest_no_scope")
    nsb = compare(results, "control", "attest", "attest_no_scope")
    h5 = None if None in (ns_foreign, foreign) else (SUPPORTED if ns_foreign > 0 and foreign == 0 else NOT_SUPPORTED)
    out.append({"id": "H5", "type": "leakage counts (exact); control pass@1 descriptive", "verdict": h5,
                "foreign_notes_shown": {"attest": foreign, "attest_no_scope": ns_foreign}, "tests": [nsb]})

    h6 = compare(results, "heldout", "attest", "attest_no_gate")
    out.append({"id": "H6", "type": "non-inferiority vs the same system without the write gate", "verdict": non_inferiority(h6),
                "tests": [h6], "regressions": {c: regress.get(c, 0) for c in ("attest", "attest_no_gate")}})
    for h in out:
        h["delta"] = DELTA
    return out


# ---------------------------------------------------------------- memory funnel: where did the needed note get lost?

FUNNEL_STAGES = ("not_in_memory", "excluded", "not_retrieved", "retrieved_not_injected", "injected")


def funnel_stage(trace: dict, pattern: str) -> tuple[str, list[str]]:
    """How far the notes about one convention got: (furthest stage, excluded reasons if stuck there)."""
    about = {i for i, text in (trace.get("texts") or {}).items() if re.search(pattern, text, re.I)}
    if not about:
        return "not_in_memory", []
    if about & set(trace.get("injected") or []):
        return "injected", []
    if about & set(trace.get("retrieved") or []):
        return "retrieved_not_injected", []
    excluded = trace.get("excluded") or {}
    if about <= set(excluded):
        return "excluded", sorted({excluded[i].split(":")[0].split(" by ")[0] for i in about})
    return "not_retrieved", []


def funnel(results: list[dict], groups=("heldout", "stale")) -> list[dict]:
    """For every (run, convention the task needs): how far a note about it got, and whether the first
    attempt then satisfied the convention (its hidden test). Separates "memory never had it" from
    "had it but filtered", "not ranked high enough", "cut before injection" and "injected but not followed".

    Notes are matched to conventions with CONVENTION_PATTERNS (approximate, the same for every system).
    """
    cells = defaultdict(lambda: {"checked": 0, **{f"{s}_{o}": 0 for s in FUNNEL_STAGES for o in ("ok", "fail")}})
    reasons = defaultdict(lambda: defaultdict(int))
    for r in results:
        first = r["attempts"][0]
        trace = (r.get("retrieval_debug") or {}).get("trace")
        if first.get("crashed") or r["group"] not in groups or trace is None:
            continue
        for conv in r.get("conventions", []):
            pattern = CONVENTION_PATTERNS.get(conv)
            if not pattern:
                continue
            stage, why = funnel_stage(trace, pattern)
            ok = conv not in first["conv_failed"]
            c = cells[(r["condition"], conv)]
            c["checked"] += 1
            c[f"{stage}_{'ok' if ok else 'fail'}"] += 1
            for w in why:
                reasons[(r["condition"], conv)][w] += 1
    rows = []
    for (cond, conv), c in sorted(cells.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, kv[0][1])):
        injected = c["injected_ok"] + c["injected_fail"]
        rows.append({"condition": cond, "convention": conv, **c,
                     "followed_when_injected": c["injected_ok"] / injected if injected else None,
                     "excluded_reasons": dict(reasons[(cond, conv)])})
    return rows


# ---------------------------------------------------------------- business risks (see SCENARIO.md)

RISKS = {
    "duplicate_money_operation": lambda task, test: test.startswith("test_conv_c5"),
    "unauthorised_operation": lambda task, test: test.startswith("test_conv_c6") and "allows" not in test,
    "legitimate_operation_blocked": lambda task, test: test.startswith("test_conv_c6_allows"),
    "amount_precision_violation": lambda task, test: test.startswith("test_conv_c1"),
    "unaudited_money_movement": lambda task, test: test.startswith("test_conv_c4"),
    # Only checks an outdated v1 rule can fail: hard-coded half-up rounding, or blocking an amount the v2 threshold allows.
    # (A blocked unapproved amount in S tasks is "unauthorised", which an agent that never knew C6 also fails.)
    "outdated_policy_applied": lambda task, test: task.startswith("S") and ("rounding_policy" in test or test.startswith("test_conv_c6_allows")),
    "rule_in_wrong_repository": lambda task, test: task.startswith("B") and test.startswith("test_conv_k"),
}


def _hidden_test_names(task_id: str) -> list[str]:
    from .benchmark import load_task
    from .verify import _parse_hidden_tests

    return [t.name for t in _parse_hidden_tests(load_task(task_id).hidden_test)]


def business_risks(results: list[dict], groups=("heldout", "stale", "control")) -> list[dict]:
    """Per condition and risk: how often the first attempt failed a check guarding against it."""
    names = {}
    cells = defaultdict(lambda: [0, 0])  # (condition, risk) -> [failed, checked]
    for r in results:
        if r["group"] not in groups or r["attempts"][0].get("crashed"):
            continue
        tid = r["task_id"]
        names.setdefault(tid, _hidden_test_names(tid))
        failed = set(r["attempts"][0].get("tests_failed", []))
        knew_c6 = not any(t.startswith("test_conv_c6_blocks") for t in failed)
        for test in names[tid]:
            for risk, applies in RISKS.items():
                # An agent that did not block the unapproved amount never applied any threshold, outdated or not:
                # its "allows" failure is not an outdated policy (re-check R1).
                if risk == "outdated_policy_applied" and test.startswith("test_conv_c6_allows") and not knew_c6:
                    continue
                if applies(tid, test):
                    cell = cells[(r["condition"], risk)]
                    cell[1] += 1
                    cell[0] += test in failed
    rows = []
    for (cond, risk), (bad, n) in sorted(cells.items(), key=lambda kv: (CONDITIONS.index(kv[0][0]) if kv[0][0] in CONDITIONS else 99, list(RISKS).index(kv[0][1]))):
        rows.append({"condition": cond, "risk": risk, "failed": bad, "checked": n, "rate": bad / n})
    return rows


def summarise(root: Path) -> dict:
    results, excluded = usable(load_results(root))
    return {
        "root": str(root),
        "runs": len(results),
        "excluded_for_leaks": [f"{r['condition']}/{r.get('rep', 1)}/{r['task_id']}" for r in excluded],
        "headline": headline(results),
        "per_task": per_task(results),
        "regressions": regressions(results),
        "contamination": contamination(results),
        "convention_hits": convention_hits(results),
        "tier_split": tier_split(results),
        "paired": paired(results),
        "attribution": attribution(results),
        "funnel": funnel(results),
        "hypothesis_tests": hypothesis_tests(results),
        "transfer_split": transfer_split(results),
        "stale_split": stale_split(results),
        "business_risks": business_risks(results),
        "stale_timeline": stale_timeline(results),
        "total_cost_usd": round(sum(r["cost_usd"] for r in results), 4),
    }

attest/benchmark.py:
"""Loading tasks and building isolated task workspaces.

Each task lives in ``benchmark/tasks/<ID>/`` (see benchmark/README.md for the
layout). A workspace is: base repository + ``setup/`` overlay + one code overlay
(``stub`` for the agent, ``naive``/``reference`` for benchmark validation).
"""

from __future__ import annotations

import json
import shutil
from dataclasses import dataclass
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
BENCHMARK_DIR = PROJECT_ROOT / "benchmark"
TASKS_DIR = BENCHMARK_DIR / "tasks"
REPOS_DIR = BENCHMARK_DIR / "repos"
# Exploratory tasks added after the main experiment; found by load_task(id), never by load_tasks().
EXTENSION_DIR = BENCHMARK_DIR / "extension"

GROUP_ORDER = {"experience": 0, "heldout": 1, "stale": 2, "control": 3, "extension": 4}


@dataclass(frozen=True)
class Task:
    id: str
    group: str  # experience | heldout | stale | control
    repo: str  # directory name under benchmark/repos
    title: str
    issue: str
    conventions: tuple[str, ...]
    naive_kind: str
    dir: Path
    transfer: str = ""  # held-out only: "near" (mirrors one experience task) or "far" (audit M4)

    @property
    def repo_name(self) -> str:
        """Logical repository name used for memory scoping (ledgerly_v2 -> ledgerly)."""
        return self.repo.split("_v")[0]

    @property
    def hidden_test(self) -> Path:
        return self.dir / "hidden_test.py"


def load_task(task_id: str) -> Task:
    tdir = TASKS_DIR / task_id
    if not tdir.exists() and (EXTENSION_DIR / task_id / "task.json").exists():
        tdir = EXTENSION_DIR / task_id
    meta = json.loads((tdir / "task.json").read_text())
    return Task(
        id=meta["id"],
        group=meta["group"],
        repo=meta["repo"],
        title=meta["title"],
        issue=meta["issue"],
        conventions=tuple(meta["conventions"]),
        naive_kind=meta.get("naive_kind", "naive"),
        dir=tdir,
        transfer=meta.get("transfer", ""),
    )


def load_tasks(group: str | None = None) -> list[Task]:
    tasks = [load_task(p.name) for p in sorted(TASKS_DIR.iterdir()) if (p / "task.json").exists()]
    if group:
        tasks = [t for t in tasks if t.group == group]
    return sorted(tasks, key=lambda t: (GROUP_ORDER[t.group], t.id))


def repo_version(repo_dir: Path) -> str:
    """Read ``__version__`` from the package's __init__.py."""
    for init in repo_dir.glob("*/__init__.py"):
        for line in init.read_text().splitlines():
            if line.startswith("__version__"):
                return line.split("=", 1)[1].strip().strip("\"'")
    return "unknown"


def _apply_overlay(src: Path, dest: Path) -> None:
    if not src.exists():
        return
    for f in sorted(src.rglob("*")):
        if f.is_dir():
            continue
        rel = f.relative_to(src)
        if f.name.endswith(".append"):
            target = dest / rel.parent / f.name[: -len(".append")]
            target.parent.mkdir(parents=True, exist_ok=True)
            existing = target.read_text() if target.exists() else ""
            target.write_text(existing.rstrip("\n") + "\n\n\n" + f.read_text())
        else:
            target = dest / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(f, target)


def materialize(task: Task, dest: Path, variant: str = "stub") -> Path:
    """Create a fresh workspace for ``task`` at ``dest`` using the given code overlay."""
    if variant not in {"stub", "naive", "reference"}:
        raise ValueError(f"unknown variant {variant!r}")
    if dest.exists():
        shutil.rmtree(dest)
    shutil.copytree(
        REPOS_DIR / task.repo,
        dest,
        ignore=shutil.ignore_patterns("__pycache__", ".pytest_cache"),
    )
    _apply_overlay(task.dir / "setup", dest)
    _apply_overlay(task.dir / variant, dest)
    return dest

attest/github_reviews.py:
"""Fetch merged pull requests with reviewer comments from a public GitHub repository.

Used by the real-repository case study and the retrospective evaluation. Needs
network access to api.github.com and a GITHUB_TOKEN (GitHub Actions provides one).

One GraphQL query returns 50 pull requests together with their reviews and
review comments, so finding reviewed PRs costs a handful of requests instead of
two per PR; only the diffs of selected PRs are fetched separately. A time budget
stops the search instead of letting it wait on rate limits indefinitely.
"""

from __future__ import annotations

import os
import time

import requests

API = "https://api.github.com"

QUERY = """
query($q: String!, $cursor: String) {
  search(query: $q, type: ISSUE, first: 50, after: $cursor) {
    pageInfo { hasNextPage endCursor }
    nodes {
      ... on PullRequest {
        number title body url mergedAt
        author { login __typename }
        reviews(first: 20) {
          nodes {
            body
            author { login __typename }
            comments(first: 30) { nodes { body author { login __typename } } }
          }
        }
      }
    }
  }
}
"""


def _headers(accept: str = "application/vnd.github+json") -> dict:
    headers = {"Accept": accept, "X-GitHub-Api-Version": "2022-11-28"}
    if os.environ.get("GITHUB_TOKEN"):
        headers["Authorization"] = f"Bearer {os.environ['GITHUB_TOKEN']}"
    return headers


def gh(path: str, accept: str = "application/vnd.github+json", **params):
    for attempt in range(3):
        try:
            resp = requests.get(f"{API}{path}", headers=_headers(accept), params=params, timeout=30)
        except (requests.ConnectionError, requests.Timeout):  # transient network failure: wait and retry
            time.sleep(10 * (attempt + 1))
            continue
        if resp.status_code in (403, 429) and "rate limit" in resp.text.lower():
            time.sleep(15 * (attempt + 1))
            continue
        resp.raise_for_status()
        return resp.text if accept.endswith("diff") else resp.json()
    raise RuntimeError(f"GitHub API kept refusing {path}")


def _graphql(variables: dict) -> dict:
    resp = requests.post(f"{API}/graphql", json={"query": QUERY, "variables": variables}, headers=_headers(), timeout=60)
    resp.raise_for_status()
    data = resp.json()
    if data.get("errors"):
        raise RuntimeError(data["errors"])
    return data["data"]["search"]


def _human(actor: dict | None, author: str) -> bool:
    return bool(actor) and actor.get("login") != author and actor.get("__typename") != "Bot" and not actor.get("login", "").endswith("[bot]")


def reviewed_merged_prs(repo: str, limit: int, max_diff: int = 120_000, budget_seconds: int = 900) -> list[dict]:
    """Merged PRs that reviewers (not the author, not bots) commented on, oldest first, with their diffs."""
    started = time.time()
    found, cursor = [], None
    q = f"repo:{repo} is:pr is:merged sort:created-desc"
    while len(found) < limit and time.time() - started < budget_seconds:
        page = _graphql({"q": q, "cursor": cursor})
        for pr in page["nodes"]:
            if not pr or not pr.get("number"):
                continue
            author = (pr.get("author") or {}).get("login", "")
            if (pr.get("author") or {}).get("__typename") == "Bot":
                continue
            comments = []
            for review in pr["reviews"]["nodes"]:
                if _human(review.get("author"), author) and (review.get("body") or "").strip():
                    comments.append(review["body"].strip())
                for c in review["comments"]["nodes"]:
                    if _human(c.get("author"), author) and (c.get("body") or "").strip():
                        comments.append(c["body"].strip())
            if not comments:
                continue
            try:
                diff = gh(f"/repos/{repo}/pulls/{pr['number']}", accept="application/vnd.github.v3.diff")
            except requests.HTTPError as exc:
                if exc.response is not None and exc.response.status_code == 406:  # GitHub refuses diffs that are too large
                    continue
                raise
            if len(diff) > max_diff:
                continue
            found.append({"number": pr["number"], "title": pr["title"], "body": (pr.get("body") or "")[:1500],
                          "url": pr["url"], "merged_at": pr.get("mergedAt") or "",
                          "comments": [c[:1200] for c in comments][:15], "diff": diff})
            print(f"found PR#{pr['number']} ({len(comments)} reviewer comments), {len(found)}/{limit}", flush=True)
            if len(found) >= limit:
                break
        if not page["pageInfo"]["hasNextPage"]:
            break
        cursor = page["pageInfo"]["endCursor"]
    return sorted(found, key=lambda p: p["merged_at"])

attest/llm.py:
"""Small JSON-in/JSON-out model client used by memory systems to distill experience.

Uses the same model and settings as the agent. Tests replace it with a scripted
function via ``set_llm``.
"""

from __future__ import annotations

import json
import os
import threading
from typing import Callable

LLMFn = Callable[[str, str], dict]

_override: LLMFn | None = None
_lock = threading.Lock()
USAGE = {"calls": 0, "prompt_tokens": 0, "completion_tokens": 0}


def set_llm(fn: LLMFn | None) -> None:
    """Replace the model with ``fn(system, user) -> dict`` (``None`` restores the real model)."""
    global _override
    _override = fn


def complete_json(system: str, user: str, model: str | None = None, thinking: str | None = None) -> dict:
    """Ask the model for a JSON object. Returns {} if no valid JSON comes back after one retry.

    ``model``/``thinking`` override the defaults, e.g. to use a different model as an
    independent judge."""
    if _override is not None:
        return _override(system, user)
    import litellm

    model = model or os.environ.get("ATTEST_MODEL", "deepseek/deepseek-flash")
    thinking = thinking or os.environ.get("ATTEST_THINKING", "off")
    kwargs: dict = {"temperature": 0.0, "drop_params": True, "response_format": {"type": "json_object"}}
    if thinking == "off":
        kwargs["extra_body"] = {"thinking": {"type": "disabled"}}
    messages = [{"role": "system", "content": system}, {"role": "user", "content": user}]
    for _ in range(2):
        resp = litellm.completion(model=model, messages=messages, **kwargs)
        with _lock:
            USAGE["calls"] += 1
            USAGE["prompt_tokens"] += resp.usage.prompt_tokens or 0
            USAGE["completion_tokens"] += resp.usage.completion_tokens or 0
        try:
            data = json.loads(resp.choices[0].message.content or "")
            if isinstance(data, dict):
                return data
        except json.JSONDecodeError:
            pass
    return {}

attest/memory/__init__.py:
"""Memory systems compared in the experiment.

Every memory system implements the same small interface so that the runner,
the prompt and the agent are identical across conditions; only the memory
block injected into the prompt differs.
"""

from __future__ import annotations

from pathlib import Path

from .ace import AcePlaybookMemory
from .base import MemorySystem, NoMemory, Retrieved
from .earned import EarnedMemory
from .reasoningbank import ReasoningBankMemory

CONDITIONS = ("no_memory", "reasoningbank", "ace", "attest", "attest_no_gate", "attest_no_scope")
# Retrieval ablation (exploratory, reported separately): same systems, embedding instead of lexical ranking.
ABLATION_CONDITIONS = ("attest", "attest_emb", "reasoningbank", "reasoningbank_emb")

__all__ = ["ABLATION_CONDITIONS", "CONDITIONS", "MemorySystem", "NoMemory", "Retrieved", "make_memory"]


def make_memory(condition: str, store_dir: Path | None) -> MemorySystem:
    if condition == "no_memory":
        return NoMemory()
    if condition == "reasoningbank":
        return ReasoningBankMemory(store_dir)
    if condition == "ace":
        return AcePlaybookMemory(store_dir)
    if condition == "attest":
        return EarnedMemory(store_dir)
    if condition in ("attest_soft", "attest_no_gate_soft"):  # D71: soft-budget injection on the main memories
        from .softbudget import SoftBudgetMemory
        return SoftBudgetMemory(store_dir, gate=condition == "attest_soft")
    if condition == "attest_no_gate":
        return EarnedMemory(store_dir, gate=False)
    if condition == "attest_no_scope":
        return EarnedMemory(store_dir, scope=False)
    if condition == "attest_emb":
        return EarnedMemory(store_dir, retriever="embedding")
    if condition in ("attest_hybrid", "attest_hybrid_rerank"):  # D47, exploratory
        return EarnedMemory(store_dir, retriever=condition.removeprefix("attest_"))
    if condition == "attest_secure":  # D51, exploratory: every optional safeguard together
        from .gateway import SecureMemory
        return SecureMemory(store_dir)
    if condition.startswith("attest_v4_") and condition.removeprefix("attest_v4_") in ("A", "B", "C", "D", "D2", "E"):  # D64/D66 arms
        from .gateway import TieredMemory
        return TieredMemory(store_dir, condition.removeprefix("attest_v4_"))
    if condition == "attest_secure_v4":  # D60: three states, rule kinds routed to tests or code checks
        from .gateway import SecureMemoryV4
        return SecureMemoryV4(store_dir)
    if condition == "attest_secure_v31":  # D59: v3 with the counterfactual check instead of R2
        from .gateway import SecureMemoryV31
        return SecureMemoryV31(store_dir)
    if condition == "attest_secure_v3":  # D57: v2 with the fixes for correct notes held
        from .gateway import SecureMemoryV3
        return SecureMemoryV3(store_dir)
    if condition == "attest_secure_v2":  # D56: D51 plus two-layer evidence, graded review, rule-level learning
        from .gateway import SecureMemoryV2
        return SecureMemoryV2(store_dir)
    if condition == "attest_general":  # D46, exploratory: general notes + 2 slots for repository-wide rules
        return EarnedMemory(store_dir, general=True, reserved=2)
    if condition == "reasoningbank_emb":
        return ReasoningBankMemory(store_dir, retriever="embedding")
    raise ValueError(f"unknown memory condition {condition!r}; choose from {CONDITIONS}")

attest/memory/ace.py:
"""Simplified reproduction of ACE, Agentic Context Engineering (Zhang et al., arXiv 2510.04618). Not the official code.

What is kept: an evolving playbook of itemised bullets in sections, each with
helpful / harmful counters; after each task a Reflector tags bullets as helpful or
harmful and a Curator proposes incremental additions; deterministic merging with
de-duplication; the whole playbook is placed in the context.

Simplifications: Reflector and Curator share one model call; pruning removes a
bullet once harmful exceeds helpful by 2; no multi-epoch offline training.
"""

from __future__ import annotations

import json
from pathlib import Path

from .. import llm
from ..benchmark import Task
from .base import MemorySystem, Retrieved, experience_packet
from .sqlite_store import open_store
from .text import jaccard

SECTIONS = ("strategies", "common_mistakes", "domain_facts")
DUPLICATE_JACCARD = 0.6

REFLECT_SYSTEM = """You are the Reflector and Curator of an evolving playbook used by a coding agent.
Given a finished task and the current playbook:
1. list the ids of playbook bullets that were helpful or harmful in this task;
2. propose at most 3 NEW bullets with insights that are not already in the playbook.
Return JSON: {"helpful": [ids], "harmful": [ids], "new_bullets": [{"section": "strategies|common_mistakes|domain_facts", "content": "..."}]}"""


class AcePlaybookMemory(MemorySystem):
    name = "ace"

    def __init__(self, store_dir: Path | None):
        self.store = open_store(store_dir)

    def _bullets(self) -> dict[str, dict]:
        return {i: it for i, it in self.store.items().items() if it["status"] == "active"}

    def _render(self, bullets: dict[str, dict]) -> str:
        lines = ["Playbook (accumulated from past tasks):"]
        for section in SECTIONS:
            rows = [it for it in bullets.values() if it["section"] == section]
            if rows:
                lines.append(f"## {section}")
                lines += [f"[{it['id']}] helpful={it['helpful']} harmful={it['harmful']} :: {it['content']}" for it in rows]
        return "\n".join(lines)

    def retrieve(self, task: Task, repo_version: str) -> Retrieved:
        bullets = self._bullets()
        items = self.store.items()
        excluded = {i: f"status {it['status']}" for i, it in items.items() if i not in bullets}
        context = self._render(bullets) if bullets else ""
        # ACE has no retrieval step: the whole playbook is injected, so retrieved == injected.
        trace = {"excluded": excluded, "candidates": len(bullets), "retrieved": sorted(bullets), "injected": sorted(bullets),
                 "memory_tokens_approx": len(context) // 4,
                 "texts": {i: f"{it.get('section', '')} {it['content']}"[:300] for i, it in items.items()}}
        if not bullets:
            return Retrieved(debug={"trace": trace})
        return Retrieved(ids=sorted(bullets), context=context, debug={"trace": trace})

    def learn(self, task: Task, repo_version: str, run: dict, transcript: str, diff: str) -> list[dict]:
        bullets = self._bullets()
        packet = experience_packet(task, repo_version, run, transcript, diff)
        playbook = self._render(bullets) if bullets else "(empty)"
        data = llm.complete_json(REFLECT_SYSTEM, f"CURRENT PLAYBOOK:\n{playbook}\n\nFINISHED TASK:\n{packet}")
        events = []
        for key in ("helpful", "harmful"):
            for bid in data.get(key) or []:
                if bid in bullets:
                    it = bullets[bid]
                    fields = {key: it[key] + 1}
                    counts = {"helpful": it["helpful"], "harmful": it["harmful"], **fields}
                    if counts["harmful"] - counts["helpful"] >= 2:
                        fields["status"] = "pruned"
                    events.append(self.store.append("update", id=bid, fields=fields, reason=f"reflector: {key} in {task.id}"))
                    it.update(fields)
        for raw in (data.get("new_bullets") or [])[:3]:
            if not isinstance(raw, dict) or not raw.get("content"):
                continue
            content = str(raw["content"]).strip()
            if any(jaccard(content, b["content"]) >= DUPLICATE_JACCARD for b in self._bullets().values()):
                events.append(self.store.append("reject", task_id=task.id, candidate=raw, reason="curator: duplicate bullet"))
                continue
            section = raw.get("section") if raw.get("section") in SECTIONS else "strategies"
            item = {
                "id": self.store.next_id("ace"),
                "section": section,
                "content": content,
                "helpful": 0,
                "harmful": 0,
                "source": {"task_id": task.id, "repo": task.repo_name, "version": repo_version},
                "status": "active",
            }
            events.append(self.store.append("add", item=item, reason=f"curator: new bullet from {task.id}"))
        return events

    def __repr__(self) -> str:  # pragma: no cover - debugging aid
        return json.dumps(self._bullets(), indent=2)

attest/memory/admission.py:
"""Trust-tiered admission (exploratory, after the main experiment): stop memory pollution at injection.

The forgetting experiment showed that verified one-off details ("the refund export
uses semicolons") crowd the team's rules out of the injected notes, and that no
forgetting policy repairs it. Admission decides, before ranking, which notes may be
injected anywhere and which only where they were learned. Explainable rules, no model
score:

  policy      the evidence names a policy or incident (POLICY_PREFIXES: FIN-, POL-, SEC-, INC-)
  convention  the source review comment states it is a team convention
  repeated    verified in at least 2 independent tasks
  candidate   anything else: a detail seen once. Stored, never deleted, injected only
              when the task names a file the note was learned in; promoted
              automatically when a second independent task verifies it.

Ranking: rules (policy, convention, repeated) with any relevance come first, then
file-matched candidates; relevance orders notes within a tier.

Limit: the simulated review comments of this benchmark mark team rules explicitly
("[team convention]"); real reviewers rarely do (REAL_HISTORY.md). On real history the
reliable signals are policy references and repetition, which take time to accumulate.
"""

from __future__ import annotations

import re

RULE_TIERS = ("policy", "convention", "repeated")
CONVENTION_RE = re.compile(r"\[team convention\]|\bteam convention\b|\bour convention\b|\bwe always\b", re.I)
# Which recorded references count as a policy or an incident: finance (FIN-), general (POL-)
# and security (SEC-) policies, incidents (INC-). The evidence parser also records ADR-, RFC-
# and CVE- references; they stay in the evidence but do not make a note a policy rule.
POLICY_PREFIXES = ("FIN", "POL", "SEC", "INC")


def _norm(text: str) -> str:
    return " ".join((text or "").split()).lower()


def policy_references(item: dict) -> list[str]:
    refs = set((item.get("source") or {}).get("references") or [])
    for ev in item.get("evidence") or []:
        refs |= set((ev.get("source") or {}).get("references") or [])
    return sorted(r for r in refs if r.split("-", 1)[0] in POLICY_PREFIXES)


def independent_tasks(item: dict) -> set[str]:
    tasks = {ev.get("task_id") for ev in item.get("evidence") or [] if ev.get("task_id")}
    tasks |= set((item.get("forgetting") or {}).get("verified_tasks") or [])
    if (item.get("source") or {}).get("task_id"):
        tasks.add(item["source"]["task_id"])
    return tasks


class Trust:
    """Trust boundary for admission (optional, D41; off unless passed to tier()).

    Without it, three signals come from the review text itself and an attacker can write them:
    a "[team convention]" label, a policy or incident id, and repetition (the same comment on two
    tasks counts as two independent tasks). With it:
      registry          a policy or incident id gives the policy tier only if it is in this
                        human-maintained set (here the synthetic company's policy list)
      trusted_comments  a convention label counts only in a comment from a trusted reviewer
                        (here: the simulated maintainer's comments; e.g. CODEOWNERS in practice)
      repetition        counts distinct pieces of evidence (different quotes), not tasks
    """

    def __init__(self, registry=(), trusted_comments=()):
        self.registry = set(registry)
        self.trusted = {_norm(c) for c in trusted_comments}


def tier(item: dict, trust: "Trust | None" = None) -> str:
    evidence = item.get("evidence") or []
    refs = policy_references(item)
    if trust is not None:
        refs = [r for r in refs if r in trust.registry]
    if refs:
        return "policy"
    comments = (item.get("source") or {}).get("review_comments") or []
    if trust is not None:
        comments = [c for c in comments if _norm(c) in trust.trusted]
    for ev in evidence:
        quote = _norm((ev.get("source") or {}).get("quote", ""))
        if (ev.get("source") or {}).get("kind") == "review_comment" and quote:
            if any(quote in _norm(c) and CONVENTION_RE.search(c) for c in comments):
                return "convention"
    if trust is not None:
        quotes = {_norm((ev.get("source") or {}).get("quote", "")) for ev in evidence} - {""}
        if len(independent_tasks(item)) >= 2 and len(quotes) >= 2:
            return "repeated"
        return "candidate"
    if len(independent_tasks(item)) >= 2:
        return "repeated"
    return "candidate"


def files_named(task) -> set[str]:
    return set(re.findall(r"[\w./-]+\.py", f"{getattr(task, 'title', '')} {getattr(task, 'issue', '')}"))


def injectable_here(item: dict, task, trust: "Trust | None" = None) -> bool:
    """Rules anywhere in their repository; a candidate only in a task that names one of its files."""
    if tier(item, trust) in RULE_TIERS:
        return True
    files = set((item.get("scope") or {}).get("files") or [])
    return bool(files & files_named(task))

attest/memory/embedding.py:
"""Embedding retrieval for the retrieval ablation (exploratory, reported separately).

A small local model (no API, no cost, deterministic on CPU) ranks notes by cosine
similarity between the task (title + issue) and each note. It plugs into the same
place as the lexical ranker (``text.rank``): same candidates, same k, same output
shape, so only the ranking function differs between the two arms.

Model and versions are pinned and recorded with every ranking (``info()``).
Document embeddings are cached by text, so a note is encoded once per process;
the cache never changes a score, only latency.
"""

from __future__ import annotations

import os
import threading
from pathlib import Path

MODEL = "BAAI/bge-small-en-v1.5"          # fastembed's ONNX build: Qdrant/bge-small-en-v1.5-onnx-Q
MODEL_REVISION = "aa8f8b060edb00e03bfdd08813a2949946c8ba55"  # Hugging Face snapshot used in development
CACHE_DIR = Path(os.environ.get("ATTEST_EMBED_CACHE", "~/.cache/attest-fastembed")).expanduser()

_lock = threading.Lock()
_model = None
_doc_cache: dict[str, list[float]] = {}
_ranker = None  # tests can install a deterministic stand-in with set_ranker()


def set_ranker(fn) -> None:
    """Replace the embedding ranker (tests). ``fn(query, docs, k) -> [(id, score)]``; None restores the model."""
    global _ranker
    _ranker = fn


def _load():
    global _model
    if _model is None:
        from fastembed import TextEmbedding

        _model = TextEmbedding(MODEL, cache_dir=str(CACHE_DIR))
    return _model


def info() -> dict:
    import importlib.metadata as md

    def ver(pkg):
        try:
            return md.version(pkg)
        except md.PackageNotFoundError:
            return None

    return {"model": MODEL, "revision": MODEL_REVISION, "fastembed": ver("fastembed"), "onnxruntime": ver("onnxruntime"),
            "similarity": "cosine (normalised embeddings, dot product)", "query_prefix": "fastembed query_embed default"}


def rank(query: str, docs: dict[str, str], k: int | None) -> list[tuple[str, float]]:
    """Top-k (doc_id, cosine) for the query; ties broken by id like the lexical ranker. k=None ranks all."""
    if _ranker is not None:
        return _ranker(query, docs, k)
    if not docs:
        return []
    import numpy as np

    with _lock:  # the experiment runs sequences in threads; one model instance, encoded serially
        model = _load()
        missing = [t for t in dict.fromkeys(docs.values()) if t not in _doc_cache]
        if missing:
            for text, vec in zip(missing, model.embed(missing)):
                _doc_cache[text] = vec
        q = np.asarray(next(iter(model.query_embed([query]))))
    ids = list(docs)
    mat = np.asarray([_doc_cache[docs[i]] for i in ids])
    mat = mat / np.linalg.norm(mat, axis=1, keepdims=True)
    scores = mat @ (q / np.linalg.norm(q))
    scored = sorted(((i, round(float(s), 4)) for i, s in zip(ids, scores)), key=lambda x: (-x[1], x[0]))
    return scored if k is None else scored[:k]

attest/memory/evidence.py:
"""Typed evidence for Attest's write gate.

A candidate note must show two different things, recorded separately:

  source   where the rule comes from: a verbatim excerpt of a review comment (or of
           the diff), plus any policy / incident references it names (FIN-2026-03,
           INC-204, ...). This proves someone asked for it; it does not prove it is right.
  applied  where the accepted change does it: a changed line of the diff, typed by
           the kind of file (code, test, doc, config) and by the change (added or
           removed). This proves it was actually done, not just said.

Verification (did the change pass) is recorded as a third, separate field by the
caller: passing tests show the code meets the tests, not that the rule is correct.

Matching is line-based and tolerates only format differences in copying (diff
markers, whitespace, case, omitted tokens): every token of a claimed line must occur,
in order, in one real line of the diff, and the lines must follow the diff's order.
Paraphrases, synonyms, swapped operators and reordered lines are rejected, and the
evidence must be a changed line (see find_applied), so a rule nobody applied still
cannot be "applied".
"""

from __future__ import annotations

import re
from dataclasses import dataclass

REFERENCE_RE = re.compile(r"\b(?:INC|FIN|SEC|POL|ADR|RFC|CVE)-\d[\d-]*\d\b")
# Tokens: identifiers, numbers with their sign, and operators as tokens of their own, so a claim with
# "<" for ">", "-1" for "1" or "!ok" for "ok" does not match (re-checks r8, D27 m2). Omitting a token
# is still allowed (D25).
WORD_RE = re.compile(r"-?\d+(?:\.\d+)?|[A-Za-z_][A-Za-z0-9_]*|->|=>|<<|>>|//|\*\*|&&|\|\||[<>=!]=|\+=|-=|[<>=!+\-*/%]")

DOC_SUFFIXES = (".md", ".rst", ".txt", ".adoc")
CONFIG_SUFFIXES = (".toml", ".cfg", ".ini", ".yaml", ".yml", ".json")


@dataclass
class ChangedLine:
    file: str
    change: str  # "added" | "removed" | "context" (unchanged; never evidence on its own)
    text: str
    hunk: int = 0  # index of the @@ hunk, so context is only accepted next to its own change


def file_kind(path: str) -> str:
    name = path.rsplit("/", 1)[-1].lower()
    if path.startswith("tests/") or "/tests/" in path or name.startswith("test_") or name.endswith("_test.py"):
        return "test"
    if name.endswith(DOC_SUFFIXES) or path.startswith("docs/") or name.startswith(("changes", "changelog", "readme")):
        return "doc"
    if name.endswith(CONFIG_SUFFIXES):
        return "config"
    return "code"


def parse_diff(diff: str) -> list[ChangedLine]:
    """Lines of a unified diff (added, removed, and unchanged context), with the file each belongs to."""
    out, current, hunk = [], "", 0
    for line in diff.splitlines():
        if line.startswith("+++ "):
            current = line[4:].strip()
            current = current[2:] if current.startswith(("a/", "b/")) else current
            hunk += 1
            continue
        if line.startswith("@@"):
            hunk += 1
            continue
        if line.startswith("--- ") or line.startswith("diff --git"):
            continue
        if line.startswith("+"):
            out.append(ChangedLine(current, "added", line[1:], hunk))
        elif line.startswith("-"):
            out.append(ChangedLine(current, "removed", line[1:], hunk))
        elif line.startswith(" "):
            out.append(ChangedLine(current, "context", line[1:], hunk))
    return out


def strip_markers(text: str) -> str:
    """Remove unified-diff markers at line starts (models often copy them into snippets)."""
    return "\n".join(line[1:] if line[:1] in "+- " and not line.startswith(("+++", "---")) else line
                     for line in (text or "").splitlines())


def normalise(text: str) -> str:
    return " ".join((text or "").split()).lower()


def sides(diff: str) -> tuple[str, str]:
    """The diff's before and after text (context plus removed / added lines), so a quote copied
    from either version of a file is contiguous even where the diff interleaves - and + lines."""
    before, after = [], []
    for line in diff.splitlines():
        if line.startswith(("+++", "---", "diff --git", "@@")):
            before.append("")
            after.append("")
        elif line.startswith("+"):
            after.append(line[1:])
        elif line.startswith("-"):
            before.append(line[1:])
        else:
            text = line[1:] if line.startswith(" ") else line
            before.append(text)
            after.append(text)
    return "\n".join(before), "\n".join(after)


def source_corpus(review_comments: list[str], diff: str) -> str:
    before, after = sides(diff)
    return normalise("\n".join(review_comments)) + " \u241e " + normalise(before) + " \u241e " + normalise(after)


def references(*texts: str) -> list[str]:
    return sorted({m.group(0) for t in texts for m in REFERENCE_RE.finditer(t or "")})


def _words(text: str) -> list[str]:
    return [w.lower() for w in WORD_RE.findall(text or "")]


def _line_matches(claim: str, actual: str) -> bool:
    """Format tolerance only, never paraphrase (D21, bounded in D25).

    A claimed line matches a real changed line if, after removing diff markers and
    normalising whitespace and case, it is a verbatim substring of at least 10
    characters, or its words (at least 3) all occur in the real line in the same
    order, so the claim may only *omit* words. A word that is not in the line, a
    synonym or a reordering never matches."""
    c, a = normalise(claim), normalise(actual)
    if len(c) >= 10 and c in a:
        return True
    words = _words(claim)
    if len(words) < 3:
        return False
    rest = iter(_words(actual))
    return all(any(w == x for x in rest) for w in words)  # ordered subsequence


def _short(claim: str) -> bool:
    return len(_words(claim)) < 3 and len(normalise(claim)) < 10


def find_applied(snippet: str, changed: list[ChangedLine], allow_removed: bool = True) -> dict | None:
    """The changed line the claimed snippet refers to, typed; None if not found.

    Rules (D25, D27, re-check of D27):
    - Every claimed line must be a real line of the diff (_line_matches: format tolerance only), and the
      lines must appear in the diff's order. A line is skipped only if it has no token at all (e.g. ")").
    - A line too short for the word rule (fewer than 3 tokens and under 10 characters) must equal a
      diff line exactly, and can never be the evidence.
    - Evidence is a changed (added, or removed) line that passes on its own. At least one is needed,
      and changed lines must be at least half of the claimed lines.
    - Unchanged context lines may surround the evidence only in the same file and hunk as an evidence
      line, so an unchanged line elsewhere (e.g. an existing `audit.clear()`) can never carry the rule.
    - Only the first evidence line is recorded, and it is always the real diff line, not the claim.
    The gate does not check that the evidence line is *about* the rule (relevance is not verified)."""
    lines = [ln.strip() for ln in strip_markers(snippet).splitlines() if ln.strip()]
    lines = [ln for ln in lines if _words(ln)]
    if not lines or len(normalise(" ".join(lines))) < 10:
        return None
    usable = [c for c in changed if c.change != "removed" or allow_removed]

    def ok(claim, c):
        if _short(claim):
            return normalise(c.text) == normalise(claim)
        return _line_matches(claim, c.text)

    found, start = [], 0  # (claim, diff line), searched in diff order
    for claim in lines:
        idx = next((i for i in range(start, len(usable)) if ok(claim, usable[i])), None)
        if idx is None:
            return None
        found.append((claim, usable[idx]))
        start = idx + 1
    evidence = [c for claim, c in found if c.change != "context" and not _short(claim)]
    changes = [c for _, c in found if c.change != "context"]
    if not evidence or len(changes) * 2 < len(found):
        return None
    hunks = {(c.file, c.hunk) for c in evidence}
    if any(c.change == "context" and (c.file, c.hunk) not in hunks for _, c in found):
        return None
    first = evidence[0]
    return {"kind": file_kind(first.file), "change": first.change, "file": first.file,
            "line": first.text.strip()[:200], "lines_matched": len(changes)}


# Relevance of the applied line (optional, after the four-case gate experiment, D37): the gate
# checks that the cited line is a real changed line, not that it is about the rule, so a note can
# cite an unrelated line of the same change. With relevance on, when the evidence quote names
# code (a call, a dotted name, a snake_case identifier or backticked code), the applied line must
# contain one of those names. Quotes that name no code cannot be checked and pass.
_CODE_RE = re.compile(r"`([^`]+)`|\b([A-Za-z_]\w*)\(|\b([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)+)\b|\b([a-z]+_[a-z0-9_]+)\b")
_IDENT_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def code_names(text: str) -> set[str]:
    names = set()
    for m in _CODE_RE.finditer(text or ""):
        frag = next(g for g in m.groups() if g)
        names |= {t.lower() for t in _IDENT_RE.findall(frag) if len(t) >= 3}
    return names


def applied_is_relevant(quote: str, applied_line: str) -> bool | None:
    """True/False if the quote names code; None if it names none (nothing to check)."""
    names = code_names(quote)
    if not names:
        return None
    return bool(names & {t.lower() for t in _IDENT_RE.findall(applied_line or "")})

attest/memory/gateway.py:
"""All the optional safeguards together, in one memory (D51; exploratory, opt-in).

Order on the write path (ROADMAP "security gateway"):
  1. secret scan (D43)             a candidate holding a secret is rejected; stored text is redacted
  2. write gate (D17-D28)          verbatim source, applied changed line, verified task
  3. semantic review (D39 + D50)   cited conflicts with existing rules, the CHANGELOG or the code;
                                   conflicting or uncertain notes are held for a person
And on the read path:
  4. trust-tiered admission (D30 + D41)  a note is a repository-wide rule only on a registered policy id,
                                   a trusted reviewer's convention label, or repetition with different
                                   quotes; anything else is injected only where it was learned
The business-policy guard (D38) is a verification setting (Settings.policy_guard), turned on by the
experiment alongside this memory. Sealing the log (D42) does not change behaviour and is not used here.
"""

from __future__ import annotations

import re

from . import admission
from .governance import GovernedMemory
from .retrieval import timed_rank


def benchmark_trust() -> admission.Trust:
    """The synthetic company's policy registry and its maintainer's review comments (as in D41)."""
    from ..benchmark import PROJECT_ROOT, TASKS_DIR
    from ..verify import _parse_hidden_tests

    registry = set(re.findall(r"\b(?:FIN|POL|SEC)-\d{4}-\d{2}\b|\bINC-\d+\b", (PROJECT_ROOT / "SCENARIO.md").read_text(encoding="utf-8")))
    trusted = {t.doc for d in sorted(TASKS_DIR.iterdir()) if (d / "hidden_test.py").exists()
               for t in _parse_hidden_tests(d / "hidden_test.py") if t.doc}
    return admission.Trust(registry, trusted)


class SecureMemory(GovernedMemory):
    def __init__(self, store_dir, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, secret_scan=True, code_review=True, **kw)
        self.trust = trust or benchmark_trust()
        self.name = "attest_secure"

    def _exclusion(self, item, task, version):
        why = super()._exclusion(item, task, version)
        if why or admission.injectable_here(item, task, self.trust):
            return why
        return "candidate: seen once, injected only in its own files"

    def ranking(self, task, k=6, version=None):
        items = self.store.items()
        scored, ms = timed_rank("lexical", f"{task.title} {task.issue}", self.candidates(task, version), None)
        key = lambda x: (0 if x[1] > 0 and admission.tier(items[x[0]], self.trust) in admission.RULE_TIERS  # noqa: E731
                         else 1 if x[1] > 0 else 2, -x[1], x[0])
        ranked = sorted(scored, key=key)
        return (ranked if k is None else ranked[:k]), ms


HIGH_RISK = re.compile(r"\b(amount|money|decimal|float|refund|credit|approv\w*|threshold|permission|audit|idempoten\w*|"
                       r"payment|balance|business.policy)\b", re.I)
# As attest.analysis.CONVENTION_PATTERNS, except that C1 also matches "float": a note about money as
# float is about the Decimal rule (added when a unit test showed a float-only poison slipping through)
CONVENTIONS = {"C1": r"round_money|half[- ]up|ROUND_HALF|quantiz|two decimal|2 decimal|Decimal|\bfloat", "C2": r"BillingError",
               "C3": r"ensure_utc|time[- ]?zone|tz-aware|aware UTC|naive", "C4": r"audit\.record|audit entr|audit trail|audit log",
               "C5": r"idempoten", "C6": r"approv"}


def about(text: str) -> set[str]:
    return {c for c, rx in CONVENTIONS.items() if re.search(rx, text, re.I)}


class SecureMemoryV2(SecureMemory):
    """D51 with the review-driven changes (D56): two-layer evidence decides what is a rule (D52),
    review verdicts are graded (D53), and failed tasks are filtered rule by rule (D54)."""

    def __init__(self, store_dir, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, trust=trust, **kw)
        self.name = "attest_secure_v2"

    # D53: conflict -> hold; uncertain + high risk -> hold unless independently validated; else admit
    def _admit_after_review(self, review, task, repo_version, run, cand, changed) -> bool:
        from .validation import independent
        if review["verdict"] == "approved":
            return True
        if review["verdict"] == "conflict":
            return False
        ev = self._evidence(task, repo_version, run, cand, changed)
        probe = {"id": None, "evidence": [ev], "source": {"review_comments": run["attempts"][0]["review_comments"],
                                                          "references": ev["source"]["references"]}}
        risky = HIGH_RISK.search(f"{cand.get('title') or ''} {cand.get('content') or ''}")
        return not risky or bool(independent(probe, self.trust))

    # D52: only independently validated notes are rules; observed ones only in their own files
    def _exclusion(self, item, task, version):
        from .validation import independent
        why = GovernedMemory._exclusion(self, item, task, version)
        if why:
            return why
        if not item.get("observed_only") and independent(item, self.trust):
            return ""
        files = set((item.get("scope") or {}).get("files") or [])
        return "" if files & admission.files_named(task) else "observed: no independent validation, injected only in its own files"

    def ranking(self, task, k=6, version=None):
        from .validation import independent
        items = self.store.items()
        scored, ms = timed_rank("lexical", f"{task.title} {task.issue}", self.candidates(task, version), None)
        rule = lambda i: not items[i].get("observed_only") and bool(independent(items[i], self.trust))  # noqa: E731
        ranked = sorted(scored, key=lambda x: (0 if x[1] > 0 and rule(x[0]) else 1 if x[1] > 0 else 2, -x[1], x[0]))
        return (ranked if k is None else ranked[:k]), ms

    # D54: from a failed task, keep only candidates unrelated to the failure whose own check passed
    def learn(self, task, repo_version, run, transcript, diff, candidates=None):
        if run["final_pass"]:
            return super().learn(task, repo_version, run, transcript, diff, candidates)
        from .. import llm
        from .base import experience_packet
        from .earned import DISTILL_SYSTEM
        from .text import related
        data = {"candidates": candidates} if candidates is not None else llm.complete_json(
            DISTILL_SYSTEM, experience_packet(task, repo_version, run, transcript, diff))
        final = run["attempts"][-1]
        failed = set(final.get("conv_failed") or [])
        kept, events = [], []
        for cand in (data.get("candidates") or [])[:3]:
            text = f"{cand.get('title') or ''} {cand.get('content') or ''}"
            conv = about(text)
            if conv & failed or any(related(text, c) for c in final.get("review_comments") or []) or not conv & set(task.conventions):
                events.append(self.store.append("reject", task_id=task.id, candidate=cand,
                                                reason="failed task: candidate touches the failure or its own check did not run (rule-level, D54)"))
            else:
                kept.append(cand)
        if not kept:
            return events + [self.store.append("reject", task_id=task.id, candidate=None, reason="task not verified: nothing kept rule by rule")]
        before = set(self.store.items())
        events += super().learn(task, repo_version, dict(run, final_pass=True), transcript, diff, kept)
        for i in set(self.store.items()) - before:  # learned from a failed task: never a rule on its own
            events.append(self.store.append("update", id=i, fields={"observed_only": True, "last_verification": {
                "task_id": task.id, "version": repo_version, "result": "failed task, rule-level",
                "how": "the task failed; this candidate is unrelated to the failure and its own convention check passed"}},
                reason="kept by rule-level validation from a failed task (observed only)"))
        return events


def check_passed(item: dict) -> bool:
    """D57 R2: every convention the note is about was checked by its source task's tests, and the task passed.
    Never uses the diff; a claim about a convention no test of that task checks is not validated."""
    from ..benchmark import load_task
    conv = about(f"{item.get('title') or ''} {item.get('content') or ''}")
    try:
        task = load_task((item.get("source") or {}).get("task_id"))
    except Exception:  # noqa: BLE001 - not a benchmark task: no checks known
        return False
    passed = ((item.get("evidence") or [{}])[0].get("verification") or {}).get("passed")
    return bool(conv) and conv <= set(task.conventions) and bool(passed)


class SecureMemoryV3(SecureMemoryV2):
    """v2 with the D57 fixes for correct notes held: R1 a conflict citing only code is uncertain (code is
    a clue); R2 a passing check of every convention the note is about is independent validation; R3 a
    conflict with an existing rule does not hold a note validated by a registered policy or trusted reviewer."""

    def __init__(self, store_dir, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, trust=trust, **kw)
        self.name = "attest_secure_v3"

    def _validated(self, item: dict) -> list[str]:
        from .validation import independent
        return independent(item, self.trust, {item.get("id"): check_passed(item)})

    def _admit_after_review(self, review, task, repo_version, run, cand, changed) -> bool:
        ev = self._evidence(task, repo_version, run, cand, changed)
        probe = {"id": "probe", "title": cand.get("title"), "content": cand.get("content"), "evidence": [ev],
                 "source": {"task_id": task.id, "review_comments": run["attempts"][0]["review_comments"],
                            "references": ev["source"]["references"]}}
        ind = self._validated(probe)
        verdict = review["verdict"]
        cites = {"code" if c["source_id"].startswith("code:") else "other" for c in review.get("conflicts") or []}
        if verdict == "conflict" and cites == {"code"}:
            verdict = "uncertain"  # R1
        if verdict == "approved":
            return True
        if verdict == "conflict":
            return bool({"policy", "reviewer"} & set(ind))  # R3
        risky = HIGH_RISK.search(f"{cand.get('title') or ''} {cand.get('content') or ''}")
        return not risky or bool(ind)

    def _exclusion(self, item, task, version):
        why = GovernedMemory._exclusion(self, item, task, version)
        if why:
            return why
        if not item.get("observed_only") and self._validated(item):
            return ""
        files = set((item.get("scope") or {}).get("files") or [])
        return "" if files & admission.files_named(task) else "observed: no independent validation, injected only in its own files"

    def ranking(self, task, k=6, version=None):
        items = self.store.items()
        scored, ms = timed_rank("lexical", f"{task.title} {task.issue}", self.candidates(task, version), None)
        rule = lambda i: not items[i].get("observed_only") and bool(self._validated(items[i]))  # noqa: E731
        ranked = sorted(scored, key=lambda x: (0 if x[1] > 0 and rule(x[0]) else 1 if x[1] > 0 else 2, -x[1], x[0]))
        return (ranked if k is None else ranked[:k]), ms


class SecureMemoryV31(SecureMemoryV3):
    """v3 with R2 replaced by the counterfactual check (D59): a passing test counts as independent
    validation only if, in the verified workspace, reverting the note's change makes a test of its
    conventions fail (every counterfactual edit, see counterfactual.counterfactuals). Without a
    workspace no check counts."""

    def __init__(self, store_dir, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, trust=trust, **kw)
        self.name = "attest_secure_v31"
        self._cf: dict = {}
        self._run_ctx = None

    def _counterfactual(self, cand: dict, ev: dict) -> dict:
        from pathlib import Path
        from .counterfactual import check_all, counterfactuals
        key = ((self._run_ctx or {}).get("task_id"), (ev.get("applied") or {}).get("file"), (ev.get("applied") or {}).get("line"),
               f"{cand.get('title')} {cand.get('content')}")  # the same line can carry a validated and an unvalidated claim
        if key in self._cf:
            return self._cf[key]
        ctx = self._run_ctx or {}
        applied = ev.get("applied") or {}
        res = {"validated": False, "status": "no workspace"}
        if ctx.get("workspace") and applied.get("file") and applied.get("line"):
            ws, f = Path(ctx["workspace"]), applied["file"]
            text = f"{cand.get('title') or ''} {cand.get('content') or ''}"
            try:
                edits = counterfactuals((ws / f).read_text(encoding="utf-8"), applied["line"].lstrip("+- "), text)
                res = check_all(ctx["task"], ws, f, edits, about(text))
            except Exception as exc:  # noqa: BLE001 - a check that cannot run never validates
                res = {"validated": False, "status": f"inconclusive: {type(exc).__name__}"}
        self._cf[key] = res
        return res

    def _validated(self, item: dict) -> list[str]:
        from .validation import independent
        return independent(item, self.trust, {item.get("id"): bool((item.get("counterfactual") or {}).get("validated"))})

    def learn(self, task, repo_version, run, transcript, diff, candidates=None):
        self._run_ctx = {"task": task, "task_id": task.id, "workspace": run.get("_workspace")}
        try:
            return super().learn(task, repo_version, run, transcript, diff, candidates)
        finally:
            self._run_ctx = None

    def _admit_after_review(self, review, task, repo_version, run, cand, changed) -> bool:
        ev = self._evidence(task, repo_version, run, cand, changed)
        cf = self._counterfactual(cand, ev)
        probe = {"id": "probe", "title": cand.get("title"), "content": cand.get("content"), "evidence": [ev], "counterfactual": cf,
                 "source": {"task_id": task.id, "review_comments": run["attempts"][0]["review_comments"],
                            "references": ev["source"]["references"]}}
        ind = self._validated(probe)
        verdict = review["verdict"]
        cites = {"code" if c["source_id"].startswith("code:") else "other" for c in review.get("conflicts") or []}
        if verdict == "conflict" and cites == {"code"}:
            verdict = "uncertain"
        if verdict == "approved":
            return True
        if verdict == "conflict":
            return bool({"policy", "reviewer"} & set(ind))
        risky = HIGH_RISK.search(f"{cand.get('title') or ''} {cand.get('content') or ''}")
        return not risky or bool(ind)

    def _admit(self, task, repo_version, run, cand, changed):
        events = super()._admit(task, repo_version, run, cand, changed)
        ev = self._evidence(task, repo_version, run, cand, changed)
        cf = self._counterfactual(cand, ev)
        for e in list(events):
            if e["type"] == "add":
                events.append(self.store.append("update", id=e["item"]["id"], fields={"counterfactual": cf},
                                                reason=f"counterfactual check: {cf['status']}"))
        return events


def three_state(*, policy: bool, counterfactual: dict | None, code: dict, reviewer: bool, repeated: bool,
                review: dict | None = None) -> dict:
    """D60: Approved / Rejected / Uncertain. Uncertain is never turned into Approved for convenience.

    counter-evidence  a team code check the change violates; a cited conflict with an existing rule or the
                      CHANGELOG (a conflict citing only code is a clue, D57 R1); the advice failing the tests
    hard evidence     a registered policy; a counterfactual test; a team code check that supports the note
    soft evidence     a trusted reviewer; repetition with different quotes
    Rejected  counter-evidence and no hard evidence
    Approved  no counter-evidence, and hard evidence or two kinds of soft evidence
    Uncertain everything else, including a trusted reviewer alone and counter-evidence against hard evidence:
              a person decides"""
    cf = counterfactual or {}
    cites = {"code" if c["source_id"].startswith("code:") else "rule" for c in (review or {}).get("conflicts") or []}
    counter = list(code.get("violations") or [])
    if (review or {}).get("verdict") == "conflict" and "rule" in cites:
        counter.append("conflict with " + ", ".join(sorted(c["source_id"] for c in review["conflicts"] if not c["source_id"].startswith("code:"))))
    if str(cf.get("status", "")).startswith("invalid"):
        counter.append("the advice fails the tests")
    # routing: a code-implementation convention is verified by the team's code checks, not by tests (a
    # behaviourally equivalent violation passes every test); a business rule by the counterfactual test
    test_counts = cf.get("validated") and not code.get("code_convention")
    hard = (["policy"] if policy else []) + (["test"] if test_counts else []) + [f"code check {c}" for c in code.get("supports") or []]
    soft = (["trusted reviewer"] if reviewer else []) + (["repeated"] if repeated else [])
    if counter and not hard:
        state = "rejected"
    elif not counter and (hard or len(soft) >= 2):
        state = "approved"
    else:
        state = "uncertain"
    return {"state": state, "counter": counter, "hard": hard, "soft": soft}


class SecureMemoryV4(SecureMemoryV31):
    """Three states (D60): approved notes are rules; uncertain ones wait for a person (shown, marked
    unconfirmed, only in their own files); rejected ones are never shown. Business rules are verified by the
    counterfactual test, code conventions by the team's code checks."""

    def __init__(self, store_dir, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, trust=trust, **kw)
        self.name = "attest_secure_v4"

    def _assess(self, cand, ev, run, task, review, diff_text) -> dict:
        from . import codechecks
        from .validation import independent
        text = f"{cand.get('title') or ''} {cand.get('content') or ''}"
        cf = self._counterfactual(cand, ev)
        probe = {"id": "probe", "title": cand.get("title"), "content": cand.get("content"), "evidence": [ev],
                 "source": {"task_id": task.id, "review_comments": run["attempts"][0]["review_comments"], "references": ev["source"]["references"]}}
        ind = independent(probe, self.trust)
        return three_state(policy="policy" in ind, counterfactual=cf, code=codechecks.run(task.repo, text, (ev.get("applied") or {}).get("line") or ""),
                           reviewer="reviewer" in ind, repeated="repeated" in ind, review=review)

    def learn(self, task, repo_version, run, transcript, diff, candidates=None):
        self._diff_text = diff
        return super().learn(task, repo_version, run, transcript, diff, candidates)

    def _admit_after_review(self, review, task, repo_version, run, cand, changed) -> bool:
        ev = self._evidence(task, repo_version, run, cand, changed)
        a = self._assess(cand, ev, run, task, review, getattr(self, "_diff_text", ""))
        self._last_assessment = a
        return a["state"] != "rejected" and not (a["state"] == "uncertain" and review.get("verdict") == "conflict" and a["counter"])

    def _admit(self, task, repo_version, run, cand, changed):
        events = super()._admit(task, repo_version, run, cand, changed)
        a = getattr(self, "_last_assessment", None)
        if a:
            for e in list(events):
                iid = e["item"]["id"] if e["type"] == "add" else None
                if iid:
                    events.append(self.store.append("update", id=iid, fields={"assessment": a},
                                                    reason=f"three-state assessment: {a['state']}"))
        return events

    def _validated(self, item: dict) -> list[str]:
        a = item.get("assessment")
        if a is None:
            return super()._validated(item)
        return a["hard"] + a["soft"] if a["state"] == "approved" else []


class TieredMemory(SecureMemoryV4):
    """v4 with one of the crowding-ablation injection policies (D64): arm "A", "B", "C" or "D" (see tiers.py)."""

    def __init__(self, store_dir, arm: str, trust: admission.Trust | None = None, **kw):
        super().__init__(store_dir, trust=trust, **kw)
        assert arm in ("A", "B", "C", "D", "D2", "E"), arm
        self.arm = arm
        self.name = f"attest_v4_{arm}"
        if arm in ("D", "D2", "E"):
            from .tiers import MAX_K
            self.max_shown = MAX_K if arm == "D" else 10

    def ranking(self, task, k=6, version=None):
        from .tiers import CORE_K, REL_FRACTION, tier
        if self.arm == "A":
            return super().ranking(task, k, version)
        items = self.store.items()
        scored, ms = timed_rank("lexical", f"{task.title} {task.issue}", self.candidates(task, version), None)
        if self.arm == "B":
            ranked = sorted(scored, key=lambda x: (-x[1], x[0]))
        elif self.arm == "C":
            ranked = sorted(scored, key=lambda x: (0 if x[1] > 0 and tier(items[x[0]]) == "core" else 1, -x[1], x[0]))
        elif self.arm in ("D2", "E"):  # D66: soft budget; E ranks by what this task type needs
            from .tiers import note_topics, task_critical
            crit = task_critical(task)
            def important(i):
                return tier(items[i]) == "core" if self.arm == "D2" else bool(note_topics(items[i]) & crit) and tier(items[i]) != "candidate"
            # important notes are kept whole even without word overlap (changed after an offline dry run, disclosed)
            first = [(i, sc) for i, sc in sorted(scored, key=lambda x: (-x[1], x[0])) if important(i)]
            others = [(i, sc) for i, sc in sorted(scored, key=lambda x: (-x[1], x[0])) if sc > 0 and not important(i)]
            best = max([sc for _, sc in others] or [0])
            ranked = first + [(i, sc) for i, sc in others if sc >= REL_FRACTION * best and tier(items[i]) != "candidate"]
        else:  # D: tiers + dynamic k, no filler
            by = {t: [(i, sc) for i, sc in sorted(scored, key=lambda x: (-x[1], x[0])) if tier(items[i]) == t and sc > 0]
                  for t in ("core", "regular", "candidate")}
            core = by["core"][:CORE_K]
            best = max([sc for _, sc in by["regular"] + by["candidate"]] or [0])
            rest = [(i, sc) for i, sc in by["regular"] + by["candidate"] if sc >= REL_FRACTION * best]
            rest.sort(key=lambda x: (0 if tier(items[x[0]]) == "regular" else 1, -x[1], x[0]))
            ranked = core + rest
        return (ranked if k is None else ranked[:k]), ms


    def retrieve(self, task, repo_version):
        r = super().retrieve(task, repo_version)
        if self.arm not in ("D2", "E"):
            return r
        from .tiers import MEMORY_BUDGET, note_topics, task_critical, tier
        if len(r.context) // 4 <= MEMORY_BUDGET:
            return r
        items = self.store.items()
        crit = task_critical(task)
        keep_full = {i for i in r.ids if (tier(items[i]) == "core" if self.arm == "D2" else bool(note_topics(items[i]) & crit))}
        lines, out = r.context.splitlines(), []
        skip = False
        for ln in lines:  # over budget: compress the other notes to their title; important notes stay whole
            m = re.match(r"- \[([\w-]+)\] ([^:]+):", ln)
            if m:
                skip = m.group(1) not in keep_full
                out.append(f"- [{m.group(1)}] {m.group(2)} (compressed: over the memory budget)" if skip else ln)
            elif not (skip and ln.startswith("  ")):
                out.append(ln)
        r.context = "\n".join(out)
        r.debug["compressed"] = sorted(set(r.ids) - keep_full)
        return r

attest/memory/review.py:
"""Human review of uncertain notes, as part of the memory's lifecycle (D62). Human-only: not exposed via MCP.

    new experience -> automatic evidence check (v4) -> uncertain -> review queue -> a business owner decides
        -> approved: a rule in long-term memory          -> rejected: retired, kept in the log
    later: a policy the approval relied on changes      -> the note goes back to uncertain, for a person again

Every decision records who decided, why, which evidence they relied on, and the repository and versions it
applies to. Rules: only a registered approver may decide; an agent identity ("agent:..."), and whoever
proposed the note, may not decide on it; only uncertain or held notes can be decided.
"""

from __future__ import annotations

import re
import time

QUEUE_STATES = ("uncertain",)
HELD = ("conflict", "pending_review")
POLICY_RE = re.compile(r"\b(?:FIN|POL|SEC|INC)-[\w-]+\b")


class ReviewRefused(PermissionError):
    pass


def queue(memory) -> list[dict]:
    """What waits for a person: uncertain notes (kept, never rules) and notes held by the reviewer."""
    out = []
    for i, it in sorted(memory.store.items().items()):
        a = it.get("assessment") or {}
        if (it["status"] in ("active", "suspect") and a.get("state") in QUEUE_STATES) or it["status"] in HELD:
            out.append({"id": i, "title": it["title"], "content": it["content"], "status": it["status"],
                        "state": a.get("state", it["status"]), "counter": a.get("counter", []), "hard": a.get("hard", []),
                        "soft": a.get("soft", []), "scope": it.get("scope"), "learned_in": (it.get("source") or {}).get("task_id"),
                        "evidence": [{"task": e.get("task_id"), "quote": (e.get("source") or {}).get("quote"),
                                      "applied": (e.get("applied") or {}).get("line")} for e in it.get("evidence") or []]})
    return out


def _check(memory, item_id: str, by: str, approvers) -> dict:
    items = memory.store.items()
    if item_id not in items:
        raise KeyError(item_id)
    it = items[item_id]
    if not by or by.startswith("agent:") or by == (it.get("source") or {}).get("proposed_by"):
        raise ReviewRefused(f"{by!r} may not decide on {item_id}: agents and the note's proposer cannot approve it")
    if by not in set(approvers or ()):
        raise ReviewRefused(f"{by!r} is not a registered approver")
    a = it.get("assessment") or {}
    if not ((it["status"] in ("active", "suspect") and a.get("state") in QUEUE_STATES) or it["status"] in HELD):
        raise ValueError(f"{item_id} is not waiting for review")
    return it


def approve(memory, item_id: str, *, by: str, reason: str, evidence: list[str], approvers, scope: dict | None = None) -> dict:
    """A person approves: the note becomes a rule, with the review recorded and its policy dependencies kept."""
    it = _check(memory, item_id, by, approvers)
    if not evidence:
        raise ValueError("say which evidence the approval relies on")
    a = dict(it.get("assessment") or {"counter": [], "hard": [], "soft": []})
    record = {"decision": "approved", "by": by, "at": round(time.time(), 3), "reason": reason, "evidence": list(evidence),
              "scope": dict(it.get("scope") or {}, **(scope or {})), "depends_on": sorted(set(POLICY_RE.findall(" ".join(evidence) + " " + reason)))}
    a.update(state="approved", hard=list(a.get("hard") or []) + [f"human review by {by}"])
    fields = {"status": "active", "assessment": a, "observed_only": False, "review": record, "scope": record["scope"]}
    return memory.store.append("update", id=item_id, fields=fields, reason=f"approved by {by}: {reason}")


def reject(memory, item_id: str, *, by: str, reason: str, approvers) -> dict:
    it = _check(memory, item_id, by, approvers)
    a = dict(it.get("assessment") or {}, state="rejected")
    record = {"decision": "rejected", "by": by, "at": round(time.time(), 3), "reason": reason}
    return memory.store.append("update", id=item_id, fields={"status": "retired", "retracted_by": by, "assessment": a, "review": record},
                               reason=f"rejected by {by}: {reason}")


def policy_changed(memory, policy_id: str, *, by: str, reason: str) -> list[dict]:
    """A policy changed: notes whose human approval relied on it go back to uncertain, for a person again."""
    events = []
    for i, it in memory.store.items().items():
        rv = it.get("review") or {}
        if rv.get("decision") == "approved" and policy_id in (rv.get("depends_on") or []) and it["status"] in ("active", "suspect"):
            a = dict(it.get("assessment") or {}, state="uncertain",
                     hard=[h for h in (it.get("assessment") or {}).get("hard", []) if not h.startswith("human review")])
            events.append(memory.store.append("update", id=i, fields={"assessment": a, "review": dict(rv, superseded_by=policy_id),
                                                                       "observed_only": True},
                                              reason=f"{policy_id} changed ({reason}; recorded by {by}): back to review"))
    return events


def supersede(memory, new_id: str, old_ids: list[str], *, by: str, reason: str, approvers) -> list[dict]:
    """D69: a person records that an approved rule replaces older ones (e.g. a new threshold policy).

    The old notes become "superseded" with superseded_by and invalid_at, so retrieval no longer shows them, but they
    stay in the append-only log (nothing is deleted; Zep-style invalidation). Only a registered approver may do it,
    never an agent, and the new note must already be an approved rule."""
    if not by or by.startswith("agent:"):
        raise ReviewRefused(f"{by!r} may not supersede rules: agents cannot change what counts as a rule")
    if by not in set(approvers or ()):
        raise ReviewRefused(f"{by!r} is not a registered approver")
    items = memory.store.items()
    new = items.get(new_id)
    if not new or (new.get("assessment") or {}).get("state") != "approved" or new["status"] not in ("active", "suspect"):
        raise ValueError(f"{new_id} is not an approved rule")
    events, now = [], round(time.time(), 3)
    for old in old_ids:
        if old == new_id or old not in items:
            raise KeyError(old)
        if items[old]["status"] in ("retired", "superseded"):
            continue
        events.append(memory.store.append("update", id=old, fields={"status": "superseded", "superseded_by": new_id, "invalid_at": now,
                                                                     "supersede": {"by": by, "reason": reason, "at": now}},
                                          reason=f"superseded by {new_id} (recorded by {by}): {reason}"))
    if events:
        events.append(memory.store.append("update", id=new_id, fields={"supersedes": sorted(set(list(new.get("supersedes") or []) + list(old_ids)))},
                                          reason=f"supersedes {', '.join(old_ids)} (recorded by {by})"))
    return events


def audit_reviews(memory, approvers) -> list[dict]:
    """D69: after the fact, check every human decision in the log against the rules above. A decision written into the
    log by any other path (a forged "approved" update) is listed: decided by an agent, by the proposer, by someone not
    registered, or without evidence."""
    allowed, out, proposer = set(approvers or ()), [], {}
    for e in memory.store.events:
        if e["type"] == "add":
            proposer[e["item"]["id"]] = (e["item"].get("source") or {}).get("proposed_by")
        if e["type"] != "update":
            continue
        f = e.get("fields") or {}
        rv = f.get("review") or {}
        a = f.get("assessment") or {}
        decided = rv.get("decision") in ("approved", "rejected")
        who = rv.get("by") or (f.get("supersede") or {}).get("by")
        if not decided and not f.get("supersede") and a.get("state") == "approved":
            # an automatic approval by the gateway is legitimate only with hard evidence (policy, test, code check)
            if not [h for h in a.get("hard") or [] if not str(h).startswith("human review")]:
                out.append({"seq": e.get("seq"), "id": e.get("id"), "by": None, "problems": ["approved without hard evidence or a person"]})
            continue
        if not (decided or f.get("status") == "superseded"):
            continue
        problems = []
        if not who:
            problems.append("no decider recorded")
        elif who.startswith("agent:"):
            problems.append("decided by an agent")
        elif who == proposer.get(e.get("id")):
            problems.append("decided by the proposer")
        elif who not in allowed:
            problems.append("decider not a registered approver")
        if rv.get("decision") == "approved" and not rv.get("evidence"):
            problems.append("approval without evidence")
        if problems:
            out.append({"seq": e.get("seq"), "id": e.get("id"), "by": who, "problems": problems})
    return out

attest/memory/secrets.py:
"""Secret scanning before anything is written to memory (optional, D43).

Memory outlives the task and is shared, so a credential that reaches a note, a quote, a changed
line or a stored review comment can later be recalled in another task. With secret scanning on:
a candidate whose title or content contains a secret is rejected; secrets anywhere else in what
is stored (evidence quotes, applied lines, review comments, rejected candidates) are redacted.
Patterns are deliberately simple and known formats only; this is a backstop, not a guarantee.
"""

from __future__ import annotations

import copy
import re

PATTERNS = {
    "aws_access_key": re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
    "stripe_key": re.compile(r"\b(?:sk|rk|pk)_(?:live|test)_[0-9A-Za-z]{16,}\b"),
    "github_token": re.compile(r"\bgh[pousr]_[A-Za-z0-9]{36,}\b"),
    "slack_token": re.compile(r"\bxox[baprs]-[A-Za-z0-9-]{10,}\b"),
    "openai_style_key": re.compile(r"\bsk-[A-Za-z0-9]{32,}\b"),
    "private_key": re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
    "canary": re.compile(r"\bATTEST_CANARY_[A-Z0-9_]+\b"),
    "assigned_secret": re.compile(r"(?i)\b(password|passwd|secret|api[_-]?key|access[_-]?token|auth[_-]?token)\b(\s*[:=]\s*['\"]?)([^\s'\",;]{8,})"),
}


# Optional (D43 hardening): long random-looking tokens catch secrets in unknown formats; context
# words ("key", "token", "secret", "password", "credential") must be near them, to spare hashes and ids.
TOKEN_RE = re.compile(r"[A-Za-z0-9+/_\-]{20,}")
CONTEXT_RE = re.compile(r"(?i)\b(key|token|secret|password|passwd|credential|api)")


def entropy(s: str) -> float:
    import math
    from collections import Counter
    n = len(s)
    return -sum(c / n * math.log2(c / n) for c in Counter(s).values()) if n else 0.0


def high_entropy(text: str, min_bits: float = 3.5) -> list[str]:
    out = []
    for m in TOKEN_RE.finditer(text or ""):
        tok = m.group(0)
        # needs a digit: CamelCase identifiers (PersonEntityStateAttribute) were flagged on the first try
        classes = sum(bool(re.search(rx, tok)) for rx in (r"[a-z]", r"[A-Z]", r"[0-9]")) if re.search(r"[0-9]", tok) else 0
        near = (text or "")[max(0, m.start() - 40): m.start()]
        if classes >= 2 and entropy(tok) >= min_bits and not re.fullmatch(r"[a-z_]+|[A-Z_]+|[0-9a-f]{20,}", tok) and CONTEXT_RE.search(near):
            out.append(tok)
    return out


def find_secrets(text: str, entropy_check: bool = False) -> list[str]:
    kinds = [kind for kind, rx in PATTERNS.items() if rx.search(text or "")]
    if entropy_check and high_entropy(text):
        kinds.append("high_entropy")
    return kinds


def redact(text: str) -> str:
    if not text:
        return text
    for kind, rx in PATTERNS.items():
        if kind == "assigned_secret":
            text = rx.sub(lambda m: f"{m.group(1)}{m.group(2)}[REDACTED:{kind}]", text)
        else:
            text = rx.sub(f"[REDACTED:{kind}]", text)
    return text


def redact_obj(obj):
    if isinstance(obj, str):
        return redact(obj)
    if isinstance(obj, list):
        return [redact_obj(x) for x in obj]
    if isinstance(obj, dict):
        return {k: redact_obj(v) for k, v in obj.items()}
    return copy.deepcopy(obj)

attest/memory/store.py:
"""Append-only event log. The current state of every memory item is derived by replaying events.

Nothing is ever deleted or edited in place, so every status change keeps its
reason and evidence: the log *is* the audit trail of the memory.

Event types:
  add      {"item": {...}}                         a new item
  update   {"id", "fields": {...}, "reason"}       shallow update (status, counters, evidence ...)
  reject   {"candidate": {...}, "reason"}          a candidate that did not pass the write gate
"""

from __future__ import annotations

import copy
import hashlib
import hmac
import json
import threading
import time
from pathlib import Path

GENESIS = "genesis"


class TamperedLog(Exception):
    """The event log failed its integrity check; it is not loaded (fail closed)."""


def _canonical(event: dict) -> bytes:
    return json.dumps({k: v for k, v in event.items() if k != "mac"}, sort_keys=True, ensure_ascii=False, default=str).encode()


def seal(event: dict, prev: str, key: bytes | None) -> dict:
    """Tamper evidence (optional, D42): link the event to the previous one and authenticate it.
    Without a key the link is a plain SHA-256 chain, which anyone who can write the file can recompute."""
    event = dict(event, prev=prev)
    data = _canonical(event)
    event["mac"] = hmac.new(key, data, hashlib.sha256).hexdigest() if key else hashlib.sha256(data).hexdigest()
    return event


def verify_events(events: list[dict], key: bytes | None = None, head: str | None = None) -> dict:
    """Check sequence, links and authentication; with `head` (the last mac, kept elsewhere) also truncation."""
    prev = GENESIS
    for n, e in enumerate(events, 1):
        if e.get("seq") != n:
            return {"ok": False, "seq": e.get("seq"), "reason": f"sequence broken at position {n}"}
        if e.get("prev") != prev:
            return {"ok": False, "seq": n, "reason": "link to the previous event broken"}
        data = _canonical(e)
        want = hmac.new(key, data, hashlib.sha256).hexdigest() if key else hashlib.sha256(data).hexdigest()
        if not hmac.compare_digest(str(e.get("mac")), want):
            return {"ok": False, "seq": n, "reason": "event content does not match its authentication code"}
        prev = e["mac"]
    if head is not None and prev != head:
        return {"ok": False, "seq": len(events), "reason": "log does not end at the anchored head (truncated or extended)"}
    return {"ok": True, "seq": None, "reason": "", "head": prev}


def checkpoint(store: "EventStore", path: Path) -> dict:
    """Write the current head (seq, mac) to a separate append-only checkpoint file (D42 hardening).

    The checkpoint file is the independent trust anchor: kept where whoever can write the log cannot
    (another repository, a signed commit, object storage with retention)."""
    cp = {"seq": len(store.events), "mac": store.head, "ts": round(time.time(), 3)}
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("a", encoding="utf-8") as f:
        f.write(json.dumps(cp) + "\n")
    return cp


def verify_checkpoints(events: list[dict], path: Path, key: bytes | None = None) -> dict:
    """The log must verify, and every checkpoint must still be in it at its position: the log may have
    grown since, but nothing up to a checkpoint was rewritten, removed or cut off."""
    check = verify_events(events, key)
    if not check["ok"]:
        return check
    for line in path.read_text(encoding="utf-8").splitlines():
        cp = json.loads(line)
        if cp["seq"] > len(events) or (cp["seq"] and events[cp["seq"] - 1].get("mac") != cp["mac"]):
            return {"ok": False, "seq": cp["seq"], "reason": f"checkpoint at event {cp['seq']} no longer matches the log"}
    return {"ok": True, "seq": None, "reason": ""}


class EventStore:
    def __init__(self, path: Path | None, *, seal_key: bytes | None = None, sealed: bool = False, head: str | None = None):
        """sealed (D42, opt-in): every new event is chained and authenticated (HMAC with seal_key, or
        SHA-256 without one); an existing sealed log is verified on load and refused if it fails."""
        self.path = path
        self._lock = threading.Lock()
        self._events: list[dict] = []
        self.sealed, self._key = sealed or seal_key is not None, seal_key
        if path and path.exists():
            self._events = [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]
            if self.sealed:
                check = verify_events(self._events, self._key, head)
                if not check["ok"]:
                    raise TamperedLog(f"{path}: {check['reason']} (event {check['seq']})")

    @property
    def head(self) -> str:
        return self._events[-1].get("mac", GENESIS) if self._events else GENESIS

    def append(self, event_type: str, **payload) -> dict:
        with self._lock:
            event = {"seq": len(self._events) + 1, "ts": round(time.time(), 3), "type": event_type, **payload}
            if self.sealed:
                event = seal(event, self.head, self._key)
            self._events.append(event)
            if self.path:
                self.path.parent.mkdir(parents=True, exist_ok=True)
                with self.path.open("a", encoding="utf-8") as f:
                    f.write(json.dumps(event, ensure_ascii=False, default=str) + "\n")
        return event

    @property
    def events(self) -> list[dict]:
        return list(self._events)

    def items(self) -> dict[str, dict]:
        state: dict[str, dict] = {}
        for e in self._events:
            if e["type"] == "add":
                state[e["item"]["id"]] = copy.deepcopy(e["item"])
            elif e["type"] == "update" and e["id"] in state:
                state[e["id"]].update(copy.deepcopy(e["fields"]))
        return state

    def next_id(self, prefix: str) -> str:
        n = sum(1 for e in self._events if e["type"] == "add") + 1
        return f"{prefix}-{n:04d}"

attest/memory/text.py:
"""Deterministic text helpers: tokenising, lexical relevance and relatedness."""

from __future__ import annotations

import math
import re

STOPWORDS = set(
    """a an and are as at be by can for from has have if in into is it its must never not of on only or so
    that the their them then there these this to use used using was were when which while will with without
    you your should does each every any all also than more most same such other new add adds return returns
    value values function functions module code issue task python file files test tests ledgerly simkit""".split()
)


def tokens(text: str) -> list[str]:
    """Lower-case word tokens; identifiers like round_money and money.round_money are kept whole as well as split."""
    out = []
    for raw in re.findall(r"[A-Za-z_][A-Za-z0-9_.]*", text or ""):
        word = raw.strip(".").lower()
        parts = [p for p in re.split(r"[._]", word) if p]
        for t in {word, *parts}:
            if len(t) >= 3 and t not in STOPWORDS:
                out.append(t)
    return out


def rank(query: str, docs: dict[str, str], k: int) -> list[tuple[str, float]]:
    """Return the top-k (doc_id, score) by idf-weighted token overlap with the query."""
    if not docs:
        return []
    doc_tokens = {d: set(tokens(t)) for d, t in docs.items()}
    n = len(docs)
    df: dict[str, int] = {}
    for toks in doc_tokens.values():
        for t in toks:
            df[t] = df.get(t, 0) + 1
    q = set(tokens(query))
    scored = []
    for d, toks in doc_tokens.items():
        score = sum(math.log(1 + n / df[t]) for t in q & toks)
        scored.append((d, round(score, 3)))
    scored.sort(key=lambda x: (-x[1], x[0]))
    return scored[:k]


def bm25_rank(query: str, docs: dict[str, str], k: int | None, k1: float = 1.5, b: float = 0.75) -> list[tuple[str, float]]:
    """Okapi BM25 (used by the hybrid retriever, D47); ties broken by id like rank()."""
    if not docs:
        return []
    toks = {d: tokens(t) for d, t in docs.items()}
    n = len(docs)
    avg = sum(len(v) for v in toks.values()) / n or 1.0
    df: dict[str, int] = {}
    for v in toks.values():
        for t in set(v):
            df[t] = df.get(t, 0) + 1
    q = set(tokens(query))
    scored = []
    for d, v in toks.items():
        tf: dict[str, int] = {}
        for t in v:
            tf[t] = tf.get(t, 0) + 1
        score = 0.0
        for t in q & tf.keys():
            idf = math.log(1 + (n - df[t] + 0.5) / (df[t] + 0.5))
            score += idf * tf[t] * (k1 + 1) / (tf[t] + k1 * (1 - b + b * len(v) / avg))
        scored.append((d, round(score, 4)))
    scored.sort(key=lambda x: (-x[1], x[0]))
    return scored[:k]


def salient(text: str) -> set[str]:
    return {t for t in tokens(text) if len(t) >= 5}


def related(a: str, b: str, min_overlap: int = 2) -> bool:
    """True when two texts share at least ``min_overlap`` salient tokens (used to attribute failures)."""
    return len(salient(a) & salient(b)) >= min_overlap


def jaccard(a: str, b: str) -> float:
    sa, sb = set(tokens(a)), set(tokens(b))
    return len(sa & sb) / len(sa | sb) if sa | sb else 0.0


def normalise(text: str) -> str:
    return " ".join((text or "").split()).lower()

attest/memory/verify.py:
"""Just-in-time verification of notes against the code (after GitHub Copilot's agentic memory).

At retrieval, each note chosen for injection is checked against the checkout the agent will
work on: do the project names it mentions still exist, and does a changelog entry newer
than the version it was learned on mention it? Copilot's agents re-read a memory's cited code
before using it; here the check is deterministic, and its result is shown to the agent next to
the note ("check before use"), so the agent re-reads the code instead of trusting the note.

Anchors (what is checked): names the note mentions that the project defines at the version
the note was learned on (functions, classes, module constants, module names, file paths) and
domain terms found in that code ("half-up" in ROUND_HALF_UP). Python builtins are not anchors.
  drifted        an anchor is missing from the current code
  review         a newer changelog entry names one of the note's names, terms or amounts
  alive          every anchor is present and no newer entry mentions it
  not checkable  no anchor and no mention
"alive" means the names a rule mentions still exist, not that the rule still holds
(RESULTS.md, forgetting V2 point 5).
"""

from __future__ import annotations

import ast
import re
from functools import lru_cache
from pathlib import Path

from ..benchmark import REPOS_DIR, repo_version
from .earned import EarnedMemory


def norm(s: str) -> str:
    return re.sub(r"[^a-z0-9]", "", s.lower())


def _version_tuple(v: str) -> tuple:
    return tuple(int(x) if x.isdigit() else 0 for x in v.split("."))


@lru_cache(maxsize=16)
def corpus(repo: Path, package: str = "ledgerly") -> dict:
    defined, idents, files = set(), set(), set()
    for p in sorted((repo / package).rglob("*.py")):
        rel = p.relative_to(repo).as_posix()
        files.add(rel)
        defined.add(p.stem)
        tree = ast.parse(p.read_text())
        for node in tree.body:
            if isinstance(node, ast.Assign):
                defined |= {t.id for t in node.targets if isinstance(t, ast.Name)}
        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                defined.add(node.name)
            elif isinstance(node, ast.Name):
                idents.add(node.id)
            elif isinstance(node, ast.Attribute):
                idents.add(node.attr)
    entries = []
    log = repo / "CHANGELOG.md"
    for block in re.split(r"^## ", log.read_text() if log.exists() else "", flags=re.M)[1:]:
        m = re.match(r"(\d+\.\d+\.\d+)", block)
        if m:
            entries.append((m.group(1), block))
    return {"defined": frozenset(defined), "norm_idents": frozenset(norm(i) for i in idents | defined),
            "files": frozenset(files), "changelog": tuple(entries)}


def mentions(text: str) -> dict:
    ids = set()
    for span in re.findall(r"`([^`]+)`", text):
        ids |= set(re.findall(r"[A-Za-z_][A-Za-z0-9_]*", span))
    for dotted in re.findall(r"\b[a-z_]+(?:\.[a-z_]+)+\b", text):
        ids |= set(dotted.split("."))
    ids |= set(re.findall(r"\b[a-z]+_[a-z0-9_]+\b", text))
    ids |= set(re.findall(r"\b[A-Z][a-z]+[A-Z][A-Za-z]+\b", text))
    ids |= set(re.findall(r"\b[A-Z][A-Z0-9_]{2,}\b", text))
    return {"ids": ids, "terms": set(re.findall(r"\b[a-z]+-[a-z]+\b", text, re.I)),
            "amounts": set(re.findall(r"\b\d+\.\d{2}\b", text)), "paths": set(re.findall(r"ledgerly/\w+\.py", text))}


def anchors(m: dict, base: dict) -> list[str]:
    out = {i for i in m["ids"] if i in base["defined"]}
    out |= {p for p in m["paths"] if p in base["files"]}
    out |= {t for t in m["terms"] if len(norm(t)) >= 5 and any(norm(t) in i for i in base["norm_idents"])}
    return sorted(out)


def present(anchor: str, c: dict) -> bool:
    if anchor.endswith(".py"):
        return anchor in c["files"]
    if anchor in c["defined"]:
        return True
    return "-" in anchor and any(norm(anchor) in i for i in c["norm_idents"])


def status(note: dict, base: dict, current: dict, first_run_matching: bool = False) -> dict:
    """Verdict of one note (title, content, version) learned on `base`, checked against `current`."""
    m = mentions(f"{note['title']} {note['content']}")
    anc = anchors(m, base)
    missing = [a for a in anc if not present(a, current)]
    newer = [text for v, text in current["changelog"] if _version_tuple(v) > _version_tuple(note["version"])]
    if first_run_matching:  # the first liveness run (kept for the record, RESULTS.md)
        words = {i for i in m["ids"] if len(i) >= 4} | m["terms"] | m["amounts"]
        changed = sorted(w for w in words if any(norm(w) in norm(t) for t in newer) and len(norm(w)) >= 4)
    else:  # project names except module names (also plain words, e.g. "money"), terms, amounts; whole words
        modules = {Path(f).stem for f in base["files"]}
        words = {i for i in m["ids"] if i in base["defined"] and i not in modules} | m["terms"] | m["amounts"]
        changed = sorted(w for w in words if any(re.search(rf"(?<![\w.]){re.escape(w)}(?![\w])", t, re.I) for t in newer))
    s = "drifted" if missing else "review" if changed else "alive" if anc else "not checkable"
    return {"status": s, "anchors": anc, "missing": missing, "changelog_mentions": changed}


def repo_for(package: str, version: str) -> Path | None:
    for d in sorted(REPOS_DIR.iterdir()):
        if (d / package).is_dir() and repo_version(d) == version:
            return d
    return None


def verify(item: dict, task) -> dict:
    """Check a stored note against the task's checkout."""
    sc = item.get("scope") or {}
    package = sc.get("repo") or "ledgerly"
    current_dir = REPOS_DIR / task.repo
    if not (current_dir / package).is_dir():
        return {"status": "not checkable", "anchors": [], "missing": [], "changelog_mentions": []}
    base_dir = repo_for(package, sc.get("observed_version") or "") or current_dir
    return status({"title": item["title"], "content": item["content"], "version": sc.get("observed_version") or "0"},
                  corpus(base_dir, package), corpus(current_dir, package))


def warning(v: dict, item: dict) -> str | None:
    seen = (item.get("scope") or {}).get("observed_version")
    if v["status"] == "drifted":
        return (f"  CHECK BEFORE USE: this note was learned on {seen}; {', '.join(v['missing'])} no longer appears in this "
                "checkout's code. Read the current code and follow it where it disagrees with the note.")
    if v["status"] == "review":
        return (f"  CHECK BEFORE USE: CHANGELOG.md entries newer than {seen} mention {', '.join(v['changelog_mentions'])}. "
                "Read them and follow them where they disagree with the note.")
    return None


def citation(item: dict) -> str | None:
    """Where the note was applied, from its latest evidence: file and changed line."""
    for ev in reversed(item.get("evidence") or []):
        applied = ev.get("applied") or {}
        if applied.get("file") and applied.get("line"):
            return f"  cited code: {applied['file']}: `{applied['line'].strip()[:160]}` (re-read it before relying on the note)"
    return None


class VerifiedMemory(EarnedMemory):
    """Attest with just-in-time verification at retrieval.

    mode "annotate": every chosen note is checked; drifted and review notes are injected with a
    "check before use" line. mode "drop": drifted notes are excluded instead (review notes
    annotated). Eligibility (scope, versions, status) is checked first, as always."""

    def __init__(self, store_dir, *, mode: str = "annotate", cite: bool = False, write_back: bool = False, **kw):
        """cite (D40): show each injected note's evidence (file and changed line) so the agent can re-read
        the code itself, as Copilot's memories carry code citations. write_back (D40): store the verdict
        on the note; a drifted note becomes suspect, so the check is not repeated from scratch."""
        super().__init__(store_dir, **kw)
        assert mode in ("annotate", "drop"), mode
        self.mode, self.cite, self.write_back = mode, cite, write_back
        self.name = f"attest_verify_{mode}" + ("_cite" if cite else "") + ("_writeback" if write_back else "")

    def _exclusion(self, item, task, version):
        why = super()._exclusion(item, task, version)
        if why or self.mode != "drop":
            return why
        v = verify(item, task)
        return f"cited code changed: {', '.join(v['missing'])} missing" if v["status"] == "drifted" else ""

    def retrieve(self, task, repo_version):
        r = super().retrieve(task, repo_version)
        items = self.store.items()
        verdicts = {i: verify(items[i], task) for i in r.ids}
        lines, out = r.context.splitlines(), []
        current = None
        for line in lines:
            m = re.match(r"- \[([\w-]+)\]", line)
            if m:
                current = m.group(1)
            out.append(line)
            if current and line.startswith("  (learned from"):
                if self.cite and current in items:
                    c = citation(items[current])
                    if c:
                        out.append(c)
                w = warning(verdicts.get(current, {}), items[current]) if current in verdicts else None
                if w:
                    out.append(w)
        r.context = "\n".join(out)
        r.debug["verification"] = {i: v["status"] for i, v in verdicts.items()}
        if self.write_back:
            for i, v in verdicts.items():
                prev = (items[i].get("verification_check") or {})
                check = {"version": repo_version, "status": v["status"], "missing": v["missing"], "changelog_mentions": v["changelog_mentions"]}
                if prev == check:
                    continue
                fields = {"verification_check": check}
                reason = f"checked against {task.repo} ({repo_version}): {v['status']}"
                if v["status"] == "drifted" and items[i]["status"] == "active":
                    fields["status"] = "suspect"
                    reason += f"; {', '.join(v['missing'])} no longer in the code, marked suspect"
                self.store.append("update", id=i, fields=fields, reason=reason)
        return r

web_engine.py:
"""Browser engine for the demo (D74). Runs inside Pyodide, in the page, and calls ONLY real Attest functions:
secret scanning, the preregistered write gate (EarnedMemory.learn with a proposed candidate), team code checks,
three-state assessment, retrieval, the review lifecycle, supersession and the decision audit. Nothing here decides
on its own; it only formats what those functions return.

Not run here, because they need things a browser does not have: the agent and the distiller (a language model) and
the counterfactual test (it runs the repository's test suite). For those the page replays recorded results and says so.
sqlite3 is not available in Pyodide; Attest uses it only as an optional storage backend, so a placeholder is installed.
"""

import json
import sys
import types

sys.modules.setdefault("sqlite3", types.ModuleType("sqlite3"))

from attest.benchmark import load_task  # noqa: E402
from attest.memory import codechecks, review  # noqa: E402
from attest.memory.earned import EarnedMemory  # noqa: E402
from attest.memory.evidence import normalise  # noqa: E402
from attest.memory.gateway import three_state  # noqa: E402
from attest.memory.secrets import find_secrets  # noqa: E402

TRUSTED_REVIEWERS = {"tech-lead"}          # who counts as a trusted reviewer in this demo (demo identities)
REGISTERED_POLICIES = {"FIN-2026-03", "FIN-2026-09", "FIN-2026-11", "INC-204"}
APPROVERS = ("owner:finance-lead",)


def check(channel: str, author: str, text: str, applied_line: str) -> str:
    """One proposed piece of experience, from one channel, checked step by step by the real functions."""
    import re
    steps = []
    secrets = find_secrets(text)
    steps.append({"step": "secret scan", "fn": "attest.memory.secrets.find_secrets", "input": text,
                  "output": secrets, "verdict": "block" if secrets else "pass"})
    reviews = [text] if channel == "review" else []
    quote_ok = bool(reviews) and normalise(text) in normalise(reviews[0])
    steps.append({"step": "is it a review comment's own words", "fn": "attest.memory.evidence.normalise",
                  "input": {"channel": channel}, "output": quote_ok,
                  "verdict": "pass" if quote_ok else "weak", "note": "" if quote_ok else "not from a review comment: issue text, docs and tool output are not review"})
    applied = bool(applied_line.strip())
    steps.append({"step": "applied in a change that passed the hidden tests", "fn": "attest.memory.evidence.find_applied",
                  "input": applied_line or "(no line)", "output": applied, "verdict": "pass" if applied else "weak"})
    trusted = author in TRUSTED_REVIEWERS
    policies = sorted(set(re.findall(r"\b(?:FIN|INC|POL|SEC)-[\w-]+\b", text)))
    registered = [p for p in policies if p in REGISTERED_POLICIES]
    steps.append({"step": "who said it", "fn": "attest.memory.admission.Trust", "input": {"author": author, "policy ids": policies},
                  "output": {"trusted reviewer": trusted, "registered policies": registered}, "verdict": "pass" if trusted or registered else "weak"})
    code = codechecks.run("ledgerly_v1", text, applied_line)
    steps.append({"step": "team code checks", "fn": "attest.memory.codechecks.run", "input": applied_line or "(no line)",
                  "output": code, "verdict": "block" if code.get("violations") else "pass" if code.get("supports") else "none"})
    state = three_state(policy=bool(registered), counterfactual=None, code=code, reviewer=trusted, repeated=False)
    by_id = {ck.id: ck for ck in codechecks.CHECKS}
    state["violated"] = [{"id": v, "rule": by_id[v].rule, "line": applied_line.strip()} for v in code.get("violations") or [] if v in by_id]
    if secrets:  # as in the MCP server (D43): a candidate that records a secret is rejected before any other check counts
        state = {**state, "state": "rejected", "counter": ["contains a secret: " + ", ".join(secrets)] + state["counter"]}
    steps.append({"step": "three-state assessment (gateway v4)", "fn": "attest.memory.gateway.three_state",
                  "input": "evidence above; counterfactual test not run in the browser", "output": state, "verdict": state["state"]})
    # The preregistered gate (Attest as evaluated in the main experiment), on the same event
    m = EarnedMemory(None)  # exactly as preregistered: no secret scan, no trust list, no semantic review
    run = {"first_pass": False, "final_pass": True, "attempts": [{"review_comments": reviews, "conv_failed": []}]}
    diff = f"--- a/ledgerly/adjustments.py\n+++ b/ledgerly/adjustments.py\n@@ -1,1 +1,2 @@\n # context\n+{applied_line}\n" if applied else ""
    task = load_task("E04")
    cand = {"kind": "lesson", "type": "code_convention", "title": text[:60], "content": text,
            "evidence_quote": text if channel == "review" else "", "applied_in_diff": applied_line}
    events = m.learn(task, "1.0.0", run, "", diff, candidates=[cand])
    gate = [{"type": e["type"], "reason": e.get("reason", "")} for e in events]
    return json.dumps({"steps": steps, "state": state, "preregistered_gate": gate})


class Governance:
    """The demo run's memory (replayed from its event log), then live review decisions on it."""

    def __init__(self, events_json: str):
        from attest.memory.gateway import SecureMemoryV4
        self.m = SecureMemoryV4(None)
        for e in json.loads(events_json):
            self.m.store.append(e["type"], **{k: v for k, v in e.items() if k not in ("seq", "ts", "type")})
        self.task = load_task("H04")

    def _out(self, ok, msg, **kw):
        return json.dumps({"ok": ok, "message": msg, **kw}, default=str)

    def queue(self):
        return json.dumps(review.queue(self.m), default=str)

    def notes(self):
        return json.dumps(list(self.m.store.items().values()), default=str)

    def approve(self, note_id, who, reason, evidence):
        try:
            review.approve(self.m, note_id, by=who, reason=reason, evidence=[e for e in evidence.split(";") if e.strip()], approvers=APPROVERS)
            return self._out(True, f"approved by {who}")
        except (review.ReviewRefused, ValueError, KeyError) as exc:
            return self._out(False, f"{type(exc).__name__}: {exc}")

    def reject(self, note_id, who, reason):
        try:
            review.reject(self.m, note_id, by=who, reason=reason, approvers=APPROVERS)
            return self._out(True, f"rejected by {who}")
        except (review.ReviewRefused, ValueError, KeyError) as exc:
            return self._out(False, f"{type(exc).__name__}: {exc}")

    def new_threshold_note(self):
        """SIMULATED: the note a task on ledgerly 2.x would teach after FIN-2026-11."""
        import copy
        items = self.m.store.items()
        if "at-0008" in items:
            return self._out(True, "already in the queue")
        new = copy.deepcopy(items["at-0005"])
        new.update(id="at-0008", title="Refunds above 1000.00 require approved_by",
                   content="Since FIN-2026-11, support refunds and credits above 1000.00 need a keyword-only approved_by.",
                   assessment={"state": "uncertain", "counter": [], "hard": [], "soft": ["reviewer"]}, review=None)
        new["source"] = dict(new.get("source") or {}, proposed_by="agent:distiller", task_id="SIMULATED")
        self.m.store.append("add", item=new, reason="SIMULATED: a note learned after FIN-2026-11 raised the threshold")
        return self._out(True, "at-0008 added to the queue (simulated note)")

    def supersede(self, new_id, old_id, who, reason):
        try:
            review.supersede(self.m, new_id, [old_id], by=who, reason=reason, approvers=APPROVERS)
            return self._out(True, f"{old_id} superseded by {new_id}")
        except (review.ReviewRefused, ValueError, KeyError) as exc:
            return self._out(False, f"{type(exc).__name__}: {exc}")

    def policy_changed(self, policy, who, reason):
        ev = review.policy_changed(self.m, policy, by=who, reason=reason)
        return self._out(True, f"{len(ev)} approval(s) that relied on {policy} went back to review", ids=[e["id"] for e in ev])

    def forge(self, note_id, who):
        """Write an approval straight into the log, bypassing review.approve, as an attacker with log access would."""
        self.m.store.append("update", id=note_id, fields={"assessment": {"state": "approved", "hard": [], "soft": []},
                                                          "review": {"decision": "approved", "by": who, "evidence": []}},
                            reason="written straight into the log (forgery test)")
        return self._out(True, "forged approval written to the log")

    def audit(self):
        return json.dumps(review.audit_reviews(self.m, APPROVERS), default=str)

    def retrieve(self):
        r = self.m.retrieve(self.task, "1.0.0")
        return json.dumps({"injected": r.ids, "excluded": (r.debug.get("trace") or {}).get("excluded", {})}, default=str)

    def log(self, n=12):
        return json.dumps([{k: e.get(k) for k in ("seq", "type", "id", "reason")} | {"item": (e.get("item") or {}).get("id")}
                           for e in self.m.store.events[-int(n):]], default=str)

from decimal import ROUND_HALF_UP, Decimal


class SimulationError(Exception):
    pass


def energy_cost(power_watts, hours, price_per_kwh):
    if power_watts < 0 or hours < 0 or price_per_kwh < 0:
        raise SimulationError("negative_input")
    cost = Decimal(str(power_watts)) / 1000 * Decimal(str(hours)) * Decimal(str(price_per_kwh))
    return cost.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

